function ypRentPicture(weeklyRent,player){const num=v=>v==null||v===''?null:(Number.isFinite(+v)?+v:null);const rent=num(weeklyRent);const income=num(player&&player.incomeWk);const expenses=num(player&&player.expenseWk);const bank=num(player&&player.bank);const rentWk=rent==null?null:Math.round(rent);const incomeWk=income==null?null:Math.round(income);const expenseWk=expenses==null?null:Math.round(expenses);const bond=rentWk==null?null:rentWk*4;const advance=rentWk==null?null:rentWk*2;const upfront=rentWk==null?null:rentWk*6;const left=incomeWk==null||expenseWk==null||rentWk==null?null:incomeWk-expenseWk-rentWk;const bankWk=bank==null?null:Math.round(bank);return {rent:rentWk,bond,advance,upfront,income:incomeWk,expenses:expenseWk,left,bank:bankWk,afterBond:bankWk==null||upfront==null?null:bankWk-upfront};}
function ypListingModel(input){input=input||{};const kind=input.kind||'rent';const codeFor=input.footprintId||input.id||'';const titles={sale:'For sale',auction:'Auction',roomshare:'Room share'};const title=kind==='rent'?(codeFor?('Property ID: '+ypPropertyIdCode(codeFor)):'Property ID'):((titles[kind]||'Property')+(input.n?' '+input.n:''));const money=[];const add=(label,amount,primary)=>{const text=ypMoneyText(amount);if(text)money.push({label,amount:text,value:Math.round(Number(amount)),primary:!!primary});};const picture=kind==='rent'?ypRentPicture(input.weeklyRent,input.player):null;if(kind==='rent')add('Weekly rent',input.weeklyRent,true);else if(kind==='sale')add('Asking price',input.price,true);else if(kind==='auction')add('Current bid',input.bid,true);else if(kind==='roomshare')add('Weekly room share',input.share,true);const flow=[];if(picture&&picture.bond!=null&&picture.advance!=null)flow.push({group:'Move-in costs',hint:'Paid when you sign the lease',kind:'due',open:true,items:[{label:'Four-week bond',hint:'Held by the bond office',amount:picture.bond},{label:'Two weeks rent in advance',hint:'Covers the first two weeks',amount:picture.advance}],total:picture.upfront});if(picture&&picture.income!=null){flow.push({group:'Expenses Snapshot',hint:'Living costs plus this rent',kind:'out',items:[{label:'Weekly expenses',hint:'Living costs before this rent',amount:picture.expenses},{label:'Weekly rent',hint:'This property',amount:picture.rent}],total:(picture.expenses||0)+(picture.rent||0)});flow.push({label:'Left after this rent',amount:picture.left,hint:'Income minus expenses minus this rent'});}if(picture&&picture.afterBond!=null&&input.status!=='active')flow.push({label:'Bank after move-in costs',amount:picture.afterBond,hint:'After the bond and two weeks rent in advance'});const st=input.appStatus||input.status||'available';const owner=input.owner==='player'?'player':'game';const limits={rent:'In-game only. Not a real vacancy. Applying does not charge you. The four-week bond and two weeks rent in advance are paid when you sign the lease.',sale:'In-game only. Not a real listing. Buying is not available, and nothing is charged.',auction:'In-game only. Not a real auction. Bidding is not available, and nothing is charged.',roomshare:'In-game only. Not a real room share. Sharing is not available, and nothing is charged.'};let action=kind==='rent'&&!input.fixture?{label:'Apply to rent',disabled:false,act:'apply'}:null;let statusText='';let limitation=limits[kind]||limits.rent;if(kind==='rent'&&!input.fixture&&st==='expired'){action=null;statusText='The test approval expired. Nothing was charged.';}else if(kind==='rent'&&!input.fixture&&st==='application-pending'){action=owner==='player'?{label:'Waiting for the owner',disabled:true,act:'pending'}:{label:'See application',disabled:false,act:'resume'};limitation=owner==='player'?'Waiting for the owner. Nothing is charged.':'The property manager is checking your application. Nothing is charged.';if(owner!=='player'&&input.hoursLeft!=null){const shown=input.hoursLeft<=1?1:Math.ceil(input.hoursLeft-1e-6);statusText=(shown===1?'About 1 game hour left.':'About '+shown+' game hours left.')+' Nothing is charged.';}}else if(kind==='rent'&&!input.fixture&&st==='approved'){action={label:'Sign the lease',disabled:false,act:'resume'};statusText='Your application was approved. Sign the lease to pay the four-week bond and two weeks rent in advance.';limitation='Weekly rent starts from the third game week.';}else if(kind==='rent'&&!input.fixture&&st==='active'){action=input.moveStep==='report'||input.moveStep==='keys'?{label:'Continue moving in',disabled:false,act:'resume'}:null;statusText='';limitation='';}if(kind==='rent'&&st==='declined'){action=input.fixture?null:{label:'Apply again',disabled:false,act:'apply'};statusText='This application was declined. '+(input.declineWhy?input.declineWhy+' ':'')+'Nothing was charged.';}if(kind==='rent'&&st==='withdrawn'){action=null;if(!statusText)statusText='This application was withdrawn. Nothing was charged.';}if(kind==='rent'&&st==='ended'){action=null;statusText='You moved out. The bond came back to you.';}const approval=(kind==='rent'&&!input.fixture&&(st==='approved'||st==='active'))?'Your application has been approved.':'';return {kind,title,place:input.place||'',money,flow,kicker:input.kicker||'',codeFor,approval,status:statusText,limitation,action,fixture:!!input.fixture,fixtureNote:input.fixture?'Fixture only. Not a live record.':''};}
function ypReadPlayerMoney(){try{if(typeof ypAffordBase==='function'){const a=ypAffordBase();return {incomeWk:Math.round(a.income),expenseWk:Math.round(a.living+a.otherExp+a.loansActual),bank:a.cash};}}catch(e){}let incomeWk=null,expenseWk=null,bank=null;try{if(typeof salaryNetWk==='function')incomeWk=salaryNetWk();if(typeof INC==='function'){const inc=INC()||{};expenseWk=(typeof GAME_EXP_MO!=='undefined'?GAME_EXP_MO:((+inc.exp||0)+(+inc.debt||0)))*12/52;}if(typeof G!=='undefined'&&G&&Number.isFinite(+G.cash))bank=+G.cash;}catch(e){}return {incomeWk,expenseWk,bank};}
function ypRentalDetail(r,clock){const player=ypReadPlayerMoney();const wall=clock&&clock.wall!=null?clock.wall:null;const hour=clock?ypHourMs(clock):null;const gameLeft=r&&r.approveGameMs!=null&&hour?(r.approveGameMs-ypGameMs(clock))/hour:null;const wallLeft=r&&r.approveAt!=null&&hour&&clock&&clock.wall!=null?(r.approveAt-clock.wall)/hour:null;const hoursLeft=r&&r.status==='application-pending'&&(gameLeft!=null||wallLeft!=null)?Math.max(0,Math.min.apply(null,[gameLeft,wallLeft].filter(v=>v!=null))):null;const secondsLeft=r&&r.status==='approved'&&r.expiresAt!=null&&wall!=null?Math.max(0,Math.ceil((r.expiresAt-wall)/1000)):null;const suburb=ypDisplaySuburb(r);const listing=ypListingModel({kind:'rent',n:r.n,place:suburb,weeklyRent:r.weeklyRent,status:r.status,owner:r.owner,moveStep:r.moveStep,declineWhy:r.declineWhy,hoursLeft,secondsLeft,paused:!!(clock&&clock.paused),player,footprintId:r.footprintId,id:r.id});const pin=r.footprintId?('Property ID: '+ypPropertyIdCode(r.footprintId)+'. The house itself is marked on the map. It is not a real vacancy, occupant, or landlord.'):'Pin on a mapped building inside the 2 km search area around '+r.placeLabel+'. The circle stays on that centre when the map moves. It is not a real vacancy, occupant, or landlord.';return {id:r.id,title:listing.title,place:suburb,weeklyRent:r.weeklyRent,bond:r.weeklyRent*4,placement:r.placement||'mapped-building',footprintId:r.footprintId||'',pin,ongoing:'Not calculated. This is not a measured building, so insurance and rates are not applied.',availability:listing.limitation,kind:r.kind,applyNote:'Apply records a preview application only. It does not charge your game balance and does not start a tenancy.',listing};}
const YP_GAME_HOURS_PER_WEEK=168;
function ypWeekMs(clock){const n=Number(clock&&clock.weekMs);return n>0?n:(typeof CFG!=='undefined'&&CFG&&CFG.weekMs>0?CFG.weekMs:YP_WEEK_MS);}
