function ypEventClockLabel(ev){return typeof ypRealClockLabel==='function'?ypRealClockLabel(ypEventWall(ev)):'';}
function ypHistoryEvent(id,kind,gameMs,reason,at){if(!id||!Number.isFinite(+gameMs))return null;const text={applied:'Applied for Rental',accepted:'Accepted',declined:'Declined',withdrawn:'Withdrawn after another tenancy was confirmed',expired:'Expired',confirmed:'Tenancy confirmed',cancelled:'Cancelled',offered:'Offer made',countered:'Seller counter-offer',agreed:'Price agreed',talksEnded:'Seller ended talks',walked:'Walked away',financeApplied:'Finance applied',financeApproved:'Finance approved',financeDeclined:'Finance declined',contract:'Contract signed',settled:'Settlement complete',condition:'Entry condition report returned',movedIn:'Moved in',tenantApproved:'Replacement tenant approved',leaseEnded:'Lease ended'}[kind];if(!text)return null;const ev={key:id+'|'+kind+'|'+gameMs,propertyId:id,kind,gameMs:+gameMs,text};if(reason)ev.reason=reason;if(at!=null&&Number.isFinite(+at))ev.at=+at;return ev;}
function ypMergeHistory(log,events){const eventsIn=Array.isArray(log&&log.events)?log.events.map(e=>({...e})):[];const seen=new Set(eventsIn.map(e=>e.key));(events||[]).forEach(e=>{if(!e||!e.key||seen.has(e.key)||!Number.isFinite(+e.gameMs))return;seen.add(e.key);const row={key:e.key,propertyId:e.propertyId,kind:e.kind,gameMs:+e.gameMs,text:e.text};if(e.reason)row.reason=e.reason;if(e.at!=null&&Number.isFinite(+e.at))row.at=+e.at;eventsIn.push(row);});const atOf=e=>e.at!=null&&Number.isFinite(+e.at)?+e.at:Infinity;eventsIn.sort((a,b)=>a.gameMs-b.gameMs||(atOf(a)-atOf(b))||(a.key<b.key?-1:1));return {version:1,events:eventsIn};}
