function ypOverlayPublicCode(coord){let id='';try{const m=typeof ypMap!=='undefined'?ypMap:window.__ypMap;if(m&&coord&&m.project&&m.getLayer&&m.getLayer('ypb-fill')){const hit=(m.queryRenderedFeatures(m.project([+coord[0],+coord[1]]),{layers:['ypb-fill']})||[]).find(f=>f.properties&&f.properties.gameId);if(hit)id=String(hit.properties.gameId);}}catch(e){}const code=typeof ypPublicCode==='function'?ypPublicCode(id):'No code';return (!code||String(code).startsWith('ypb-')||/^yp-[0-9a-f]{8}-/i.test(String(code)))?'No code':code;}function ypFoot(extra){const el=document.getElementById('yp-foot');if(!el)return;el.textContent=extra?extra+' '+YP_LIMIT:YP_LIMIT;}
