function ypSaleListItems(place){if(!place||!Number.isFinite(+place.lon)||!Number.isFinite(+place.lat))return {status:'none',items:[]};const suburb=ypSearchedSuburb(place);const features=window.__ygParts&&window.__ygParts.adopted&&window.__ygParts.adopted.features||[];const owned=ypOwnedFootprints();const seen=new Set();const out=[];let pending=!ypOverlayPartsReady();for(const feature of features){const props=feature&&feature.properties||{};const id=String(props.gameId||'');if(!id||seen.has(id)||!ypCardEligible(props)||String(props.tone||'')!=='home'||owned.has(id))continue;const ring=ypOuterRings(feature.geometry)[0];const point=ring&&ypFootprintPoint(ring);if(!point||ypDistanceM(+place.lon,+place.lat,point.lon,point.lat)>2000)continue;seen.add(id);const official=ypOfficialSuburb(id);if(!official){pending=true;ypPublicCode(id);continue;}if(suburb&&ypSuburbKey(official)!==ypSuburbKey(suburb))continue;out.push({feature,id,official,lon:point.lon,lat:point.lat});}out.sort((a,b)=>a.feature.properties.estimate-b.feature.properties.estimate);return {status:'ready',items:out,pending};}
