function ypRenderAreaList(){ypExclusive('yp-rent-list');const sale=window.__ypListKind==='sale';let panel=document.getElementById('yp-rent-list');if(!panel){panel=document.createElement('div');panel.id='yp-rent-list';panel.setAttribute('role','dialog');document.body.appendChild(panel);}const title=sale?'For sale':'Available rentals';panel.setAttribute('aria-label',title);const card=document.createElement('div');card.className='card';const centre=window.__ypListCentre;const where=centre?(ypSearchedSuburb(centre)||String(centre.label||'').split(',')[0]):'';let rows=[],noteText='';if(sale){const result=ypSaleListItems(centre);rows=result.items.map(item=>({id:item.id,meta:item.official,price:ypMoneyText(item.feature.properties.estimate),open:()=>{panel.remove();ypShowSaleOnMap(item);}}));noteText=result.status!=='ready'?'Search a town or suburb first.':rows.length?rows.length+(rows.length===1?' home':' homes')+' for sale in '+where+', within 2 km. Cheapest first.'+(result.pending?' Still loading more.':''):result.pending?'Loading homes for sale in '+where+'…':'No homes for sale in '+where+' within 2 km.';if(result.pending&&!panel.dataset.ypRetry){panel.dataset.ypRetry='1';setTimeout(()=>{delete panel.dataset.ypRetry;if(panel.isConnected&&window.__ypListKind==='sale')ypRenderAreaList();},1500);}}else{const result=ypRadiusList(ypReadStock(),centre);rows=result.items.map(r=>{const d=ypRentalDetail(r);const rent=ypMoneyText(d.weeklyRent);return {id:r.footprintId||r.id,meta:d.place,price:rent?rent+' a week':'',rentalId:r.id,open:()=>ypOpenRentalDetail(r.id)};});noteText=result.status!=='ready'?'Search a town or suburb first.':rows.length?rows.length+(rows.length===1?' rental':' rentals')+' within 2 km of '+where+'.':'No rentals within 2 km of '+where+'.';}const page=ypPage(rows,window.__ypListPage||1,20);const head=ypCardHeader({title,onClose:()=>panel.remove()});const note=document.createElement('p');note.id='yp-area-list-note';note.textContent=noteText;card.append(head,note);page.items.forEach(row=>{const btn=document.createElement('button');btn.type='button';btn.className='yp-rent-row';btn.dataset.id=row.rentalId||row.id;const rt=document.createElement('span');rt.className='yp-row-title';rt.appendChild(ypPropertyIdLabel(row.id));const rm=document.createElement('span');rm.className='yp-row-meta';rm.textContent=row.meta;const rp=document.createElement('span');rp.className='yp-row-price';rp.textContent=row.price;btn.append(rt,rm,rp);btn.addEventListener('click',row.open);card.appendChild(btn);});if(page.pages>1){const prev=document.createElement('button');prev.type='button';prev.id='yp-rent-prev';prev.className='hwx';prev.textContent='Previous';prev.disabled=page.page<=1;const next=document.createElement('button');next.type='button';next.id='yp-rent-next';next.className='hwx';next.textContent='Next';next.disabled=page.page>=page.pages;prev.addEventListener('click',()=>{window.__ypListPage=page.page-1;ypRenderAreaList();});next.addEventListener('click',()=>{window.__ypListPage=page.page+1;ypRenderAreaList();});card.append(prev,next);}const back=document.createElement('button');back.type='button';back.className='hwx';back.id='yp-rent-list-back';back.textContent='Back to map';back.addEventListener('click',()=>panel.remove());card.appendChild(back);panel.replaceChildren(card);}
