/* Step 3: the player signs. Pays the four-week bond and two weeks rent in advance, starts the lease, cancels other applications; moving from another rental ends that lease and returns its bond. */
function ypSignLease(id,months){ypSyncSample();if(typeof G==='undefined'||!G)return {ok:false,why:'The game is not ready.'};const store=ypReadStock();const r=(store.rentals||[]).find(x=>x.id===id);if(!r||r.status!=='approved')return {ok:false,why:'This lease is not ready to sign.'};months=typeof ypLeaseTermMonths==='function'?ypLeaseTermMonths(months):(LEASE_WKS[months]?+months:12);const pic=ypRentPicture(r.weeklyRent,null);const M=ypMoneyText;const clock=ypReadClock();const gm=ypGameMs(clock),at=clock.wall,week=G.week|0;const rentStart=typeof ypLeaseRentStartWeek==='function'?ypLeaseRentStartWeek(week):week+3;const endWeek=typeof ypLeaseEndWeek==='function'?ypLeaseEndWeek(rentStart,months):rentStart+(LEASE_WKS[months]||52);let refund=0;store.rentals.forEach(x=>{if(x.id!==id&&x.status==='active'&&x.bondCharged)refund+=Math.max(0,+x.bondPaid||0);});const cash=+G.cash;if(!(cash+refund>=pic.upfront))return {ok:false,why:'You need '+M(pic.upfront)+' for the bond and two weeks rent in advance, and you have '+M(cash+refund)+'.'};const events=[];store.rentals.forEach(x=>{if(x.id===id)return;if(x.status==='active'&&x.bondCharged){const back=Math.max(0,+x.bondPaid||0);x.status='ended';x.bondCharged=false;x.endedAt=at;x.bondRefunded=back;const ev=ypHistoryEvent(x.id,'leaseEnded',gm,'You moved out. Bond '+M(back)+' refunded',at);if(ev)events.push(ev);}else ypCancelPending(x,gm,events,at);});Object.assign(r,{status:'active',bondCharged:true,bondPaid:pic.bond,advancePaid:pic.advance,advanceUsed:0,leaseMonths:months,startWeek:rentStart,endWeek:endWeek,lastChargedWeek:rentStart-1,confirmedAt:at,moveStep:'report'});const ev=ypHistoryEvent(r.id,'confirmed',ypRentMs(r,clock),months+'-month lease signed. Bond '+M(pic.bond)+' lodged with the bond office, '+M(pic.advance)+' rent in advance',at);if(ev)events.push(ev);G.cash=cash-pic.upfront+refund;ypWriteStock(store);G.statusLease=months;if(G.lease&&G.lease.id!==(r.footprintId||r.id))G.lease.broken=0;if(typeof ypBeginConfirmedTenancy==='function'){if(G.lease&&G.lease.id!==(r.footprintId||r.id))G.lease=null;ypBeginConfirmedTenancy(r);}if(typeof log==='function')log('Lease signed '+ypRentName(r)+': bond '+M(pic.bond)+' + 2 weeks rent '+M(pic.advance),-pic.upfront);if(refund&&typeof log==='function')log('Bond refunded',refund);ypRecordHistory(events);if(typeof save==='function')save();if(typeof hud==='function')hud();if(typeof ypSyncHeader==='function')ypSyncHeader();return {ok:true,charged:pic.upfront,refund};}

function ypSettleSampleWeek(board){if(typeof G==='undefined'||!G)return;const store=ypReadStock();const covered=!!(G.homeChosen&&G.lease&&!G.lease.broken);let credit=0;if(covered)(store.rentals||[]).forEach(r=>{if(r.status!=='active'||!r.bondCharged||!r.advancePaid||(r.footprintId||r.id)!==G.lease.id)return;const wk=(G.week|0)-(r.startWeek|0);if(wk>=1&&wk<=2&&!(r.advanceUsed>=wk)){credit+=Math.round(+G.lease.rent||0);r.advanceUsed=wk;}});if(credit){G.cash+=credit;ypWriteStock(store);}const result=ypChargeSampleWeek(ypReadStock(),G.week|0);if(!result.charged){if(credit){if(typeof save==='function')save();if(typeof hud==='function')hud();}return;}if(!covered){if(board)G.cash+=board;G.cash-=result.charged;}ypWriteStock(result.store);if(typeof save==='function')save();if(typeof hud==='function')hud();}
function ypOpenRentalDetail(id,note){ypExclusive('yp-rent-detail');clearInterval(ypAppTimer);const clock=ypReadClock();const rental=ypSyncSample(clock).rentals.find(r=>r.id===id);if(!rental){ypOpenMissingOffer(id);return;}ypEnsureSuburbName(rental);const d=ypRentalDetail(rental,clock);d.listing.history=ypHistoryFor(ypReadHistory(),id);if((rental.status==='active'||rental.status==='approved')&&!d.listing.history.some(e=>e.kind==='accepted'||e.kind==='confirmed')){const at=Number.isFinite(+rental.confirmedAt)?+rental.confirmedAt:(Number.isFinite(+rental.approveAt)?+rental.approveAt:null);const ev=ypHistoryEvent(id,rental.status==='active'?'confirmed':'accepted',ypGameMs(clock),null,at);if(ev)d.listing.history=d.listing.history.concat([ev]);}let panel=document.getElementById('yp-rent-detail');if(panel)panel.remove();panel=document.createElement('div');panel.id='yp-rent-detail';panel.dataset.ypId=id;panel.setAttribute('role','dialog');panel.setAttribute('aria-labelledby','yp-listing-title');const card=document.createElement('div');ypMountListing(card,d.listing);ypHeaderDismiss(card.querySelector('.hwh'),()=>{clearInterval(ypAppTimer);panel.remove();});if(rental.footprintId){const pin=document.createElement('p');pin.className='yp-limit';pin.id='yp-rent-pin';pin.appendChild(ypPropertyIdLabel(rental.footprintId));pin.append('. The house itself is marked on the map. It is not a real vacancy, occupant, or landlord.');card.appendChild(pin);}else if(d.pin){const pin=document.createElement('p');pin.className='yp-limit';pin.id='yp-rent-pin';pin.textContent=d.pin;card.appendChild(pin);}if(rental.status==='withdrawn'){const gone=document.createElement('p');gone.className='yp-status';gone.textContent='This application was withdrawn because another rental was confirmed. Nothing was charged. History is read only.';card.appendChild(gone);}if(note){const warn=document.createElement('p');warn.className='yp-status';warn.id='yp-short';warn.textContent=note;card.appendChild(warn);}if(d.listing.action&&rental.status!=='withdrawn'){const apply=document.createElement('button');apply.type='button';apply.className='hwb';apply.id='yp-rent-apply';apply.textContent=d.listing.action.label;apply.disabled=!!d.listing.action.disabled;apply.addEventListener('click',()=>{clearInterval(ypAppTimer);if(d.listing.action.act==='apply')ypOpenRentStep(id,'apply');else if(d.listing.action.act==='resume')ypResumeRent(id);});card.appendChild(apply);}if(rental.status==='active')ypMountPayoutButton(card,rental);const back=document.createElement('button');back.type='button';back.className='hwx';back.textContent='Back';back.addEventListener('click',()=>{clearInterval(ypAppTimer);panel.remove();});card.appendChild(back);panel.appendChild(card);document.body.appendChild(panel);if(rental.status==='application-pending'||rental.status==='approved'){ypAppTimer=setInterval(()=>{if(!document.getElementById('yp-rent-detail')){clearInterval(ypAppTimer);return;}const before=rental.status;const cur=ypSyncSample(ypReadClock()).rentals.find(r=>r.id===id);if(!cur||cur.status!==before)ypOpenRentalDetail(id);},1000);}}
function ypOpenMissingOffer(id){ypExclusive('yp-rent-detail');let panel=document.getElementById('yp-rent-detail');if(panel)panel.remove();panel=document.createElement('div');panel.id='yp-rent-detail';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Application');const card=document.createElement('div');card.className='card yp-listing';const head=document.createElement('div');head.className='hwh';const h=document.createElement('h2');h.textContent='Application';head.appendChild(h);ypHeaderDismiss(head,()=>panel.remove());const copy=document.createElement('p');copy.className='yp-limit';copy.textContent=id?'This application is no longer open. Nothing was charged.':'That notice does not match a current rental application.';const back=document.createElement('button');back.type='button';back.className='hwx';back.textContent='Back';back.addEventListener('click',()=>panel.remove());card.append(head,copy,back);panel.appendChild(card);document.body.appendChild(panel);}
/* Buying a map building. Same shape as the rental flow: offer, reply, finance check after 1 game hour, bell notification, confirm, then settlement. */
const YP_NEGOTIATION={floorMin:0.92,floorMax:1.00,lowball:0.80,maxRounds:4,stepMin:0.30,stepMax:0.70,cooldownDays:1,roundTo:1000};/* tune the seller here: hidden floor as a share of the estimate, lowball cut-off, counter-offers before talks end, how far each counter drops toward the floor, game days before a new offer */
const YP_AGENT_LINES={counter:['The seller would come down to this.','My vendor can meet you part of the way.','We have had interest at this level. This is where they would sell.'],agreed:'Good news. The seller has accepted your offer.',lowball:'That offer is too far below what the seller will consider. They have ended talks for now.',rounds:'The seller has heard enough offers for now and has ended talks.'};
const YP_SETTLE_DAYS=30,YP_BUY_KEY='yp.previewBuys.v1';
function ypSeedRand(seed){let h=2166136261;for(const c of String(seed)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}let t=h+0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;}
function ypReadBuys(){try{const o=JSON.parse(localStorage.getItem(YP_BUY_KEY)||'null');if(o&&o.version===1&&o.buys)return o;}catch(e){}return {version:1,buys:{}};}
function ypWriteBuys(s){try{localStorage.setItem(YP_BUY_KEY,JSON.stringify(s));}catch(e){}}
function ypBuyFor(id){return ypReadBuys().buys[id]||null;}
function ypSaveBuy(rec){const s=ypReadBuys();s.buys[rec.id]=rec;ypWriteBuys(s);return rec;}
function ypDayMs(clock){return ypWeekMs(clock)/7;}
function ypBuyName(id){const c=ypPropertyIdCode(id);return /^[A-Z]{3}-\d{4}$/.test(c)?'Property ID: '+c:'your property';}
function ypSellerFloor(id,est){const n=YP_NEGOTIATION;return Math.min(est,Math.ceil(est*(n.floorMin+(n.floorMax-n.floorMin)*ypSeedRand('floor|'+id))/n.roundTo)*n.roundTo);}
function ypBuyRecord(feature){const p=feature.properties;return ypBuyFor(p.gameId)||{id:p.gameId,estimate:p.estimate,tone:p.tone,geometry:feature.geometry,floor:ypSellerFloor(p.gameId,p.estimate),status:'open',round:0,ask:p.estimate,lastOffer:0};}
function ypBuyFeature(rec){return {type:'Feature',properties:{gameId:rec.id,estimate:rec.estimate,tone:rec.tone,adopted:true,eligible:true},geometry:rec.geometry};}
function ypBuyEvent(rec,kind,reason,clock){rec.seq=(rec.seq|0)+1;return ypHistoryEvent(rec.id,kind,ypGameMs(clock)+rec.seq/1000,reason,clock.wall);}
function ypCanOffer(rec,clock){if(!rec)return true;if(['finance-choice','finance-pending','approved','contract','owned'].includes(rec.status))return false;if(rec.status!=='ended')return true;const wait=ypDayMs(clock)*YP_NEGOTIATION.cooldownDays;return ypGameMs(clock)>=rec.endedGameMs+wait||clock.wall>=rec.endedAt+wait;}
function ypSellerReply(rec,offer){const n=YP_NEGOTIATION;const r=ypSeedRand('reply|'+rec.id+'|'+rec.round+'|'+offer);if(offer>=rec.floor||offer>=rec.ask)return {kind:'agreed',price:Math.min(offer,rec.ask),line:YP_AGENT_LINES.agreed};if(offer<rec.estimate*n.lowball)return {kind:'ended',reason:'Offer too low',line:YP_AGENT_LINES.lowball};if(rec.round>=n.maxRounds)return {kind:'ended',reason:'Too many rounds',line:YP_AGENT_LINES.rounds};const step=n.stepMin+(n.stepMax-n.stepMin)*r;const price=Math.max(rec.floor,Math.ceil((rec.ask-(rec.ask-rec.floor)*step)/n.roundTo)*n.roundTo);return {kind:'counter',price,line:YP_AGENT_LINES.counter[Math.floor(r*YP_AGENT_LINES.counter.length)%YP_AGENT_LINES.counter.length]};}
function ypAgree(rec,price,clock,events){rec.agreed=price;events.push(ypBuyEvent(rec,'agreed','Agreed price '+ypMoneyText(price),clock));ypStartFinance(rec,clock,events);}
/* a loan goes to the bank for 1 game hour; paying the full price in cash needs no loan, so it is approved straight away */
function ypStartFinance(rec,clock,events){const b=ypSaleBreakdown(rec.agreed,ypDepFor(rec,rec.agreed),rec);if(b.q.loan<=0&&b.ok){rec.status='approved';events.push(ypBuyEvent(rec,'financeApproved','Cash purchase, no loan needed',clock));return;}if(!rec.intent){rec.status='finance-choice';return;}rec.status='finance-pending';rec.approveGameMs=ypGameMs(clock)+ypHourMs(clock);rec.approveAt=clock.wall+ypHourMs(clock);}
function ypBuyCommit(rec,events){ypSaveBuy(rec);ypRecordHistory(events.filter(Boolean));if(typeof save==='function')save();}
function ypSubmitOffer(feature,offer,dep){ypSyncBuys();const clock=ypReadClock();const rec=ypBuyRecord(feature);offer=Math.round(+offer);if(!(offer>0)||!ypCanOffer(rec,clock))return {ok:false,reason:'locked'};if(dep){delete rec.depPct;delete rec.depAmt;if(dep.pct)rec.depPct=dep.pct;else rec.depAmt=dep.amt;}if(rec.status==='negotiating'&&offer<=rec.lastOffer)return {ok:false,reason:'higher'};if(rec.status!=='negotiating')Object.assign(rec,{round:0,ask:rec.estimate,lastOffer:0});const reply=ypSellerReply(rec,offer);const events=[ypBuyEvent(rec,'offered','Your offer '+ypMoneyText(offer),clock)];rec.lastOffer=offer;rec.line=reply.line;if(reply.kind==='agreed')ypAgree(rec,reply.price,clock,events);else if(reply.kind==='counter'){rec.round++;rec.ask=reply.price;rec.status='negotiating';events.push(ypBuyEvent(rec,'countered','Seller asks '+ypMoneyText(reply.price),clock));}else{rec.status='ended';rec.endedGameMs=ypGameMs(clock);rec.endedAt=clock.wall;events.push(ypBuyEvent(rec,'talksEnded',reply.reason,clock));}ypBuyCommit(rec,events);return {ok:true,reply};}
function ypAcceptCounter(id){const clock=ypReadClock();const rec=ypBuyFor(id);if(!rec||rec.status!=='negotiating')return;const events=[];rec.line=YP_AGENT_LINES.agreed;ypAgree(rec,rec.ask,clock,events);ypBuyCommit(rec,events);}
function ypWalkAway(id){const clock=ypReadClock();const rec=ypBuyFor(id);if(!rec||rec.status!=='negotiating')return;Object.assign(rec,{status:'walked',round:0,ask:rec.estimate,lastOffer:0});ypBuyCommit(rec,[ypBuyEvent(rec,'walked','You walked away',clock)]);}
function ypBuyNotify(rec,msg){if(typeof notify!=='function')return;notify('info',msg,null,true);const n=G.notifs&&G.notifs[0];if(n)n.ypBuy=rec.id;}
function ypSyncBuys(){if(typeof G==='undefined'||!G)return;try{ypSyncLoanBalances();}catch(e){}try{ypSyncOverlap();}catch(e){}const clock=ypReadClock();const s=ypReadBuys();const events=[];let changed=false;Object.values(s.buys).forEach(rec=>{if(rec.status==='finance-pending'&&(ypGameMs(clock)>=rec.approveGameMs||clock.wall>=rec.approveAt)){changed=true;const b=ypSaleBreakdown(rec.agreed,ypDepFor(rec,rec.agreed),rec);if(b.ok){rec.status='approved';events.push(ypBuyEvent(rec,'financeApproved',b.L.name+' approved the loan',clock));ypBuyNotify(rec,'The bank approved your loan for '+ypBuyName(rec.id)+'. Tap to sign the contract.');}else{rec.status='declined';rec.declineWhy=b.why;rec.needDep=b.need;events.push(ypBuyEvent(rec,'financeDeclined',b.why,clock));ypBuyNotify(rec,'The bank declined your loan for '+ypBuyName(rec.id)+'. Tap to see why. Nothing was charged.');}}if(rec.status==='contract'&&ypGameMs(clock)>=rec.settleGameMs){changed=true;G.cash-=rec.atSettle;rec.status='owned';if(!Number.isFinite(+rec.loanStart))rec.loanStart=+rec.loan||0;rec.loan=+rec.loanStart||+rec.loan||0;rec.loanPaidToWeek=(typeof G!=='undefined'&&G?G.week|0:0);let overlapNote='';if(rec.intent==='live'){const ov=ypStartOverlapLease(rec,clock);if(ov){const pay=ypPayoutQuote(ov);overlapNote=' You keep paying rent at '+ypPublicCode(ov.footprintId||ov.id)+' until a new tenant moves in.'+(pay?' You can pay out the lease now for '+ypMoneyText(pay.pay)+'.':'');}}log('Settled '+ypBuyName(rec.id)+': rest of deposit + duty '+ypMoneyText(rec.duty)+(rec.lmi?' + LMI '+ypMoneyText(rec.lmi):'')+' + legals',-rec.atSettle);events.push(ypBuyEvent(rec,'settled','Paid at settlement '+ypMoneyText(rec.atSettle)+'.'+(rec.intent==='live'?' You moved in.'+overlapNote:''),clock));ypBuyNotify(rec,"You've moved into "+ypBuyName(rec.id)+'.'+(overlapNote||' Keys collected — you now own '+ypBuyName(rec.id)+'.'));}});if(!changed)return;ypWriteBuys(s);ypRecordHistory(events);if(typeof save==='function')save();if(typeof hud==='function')hud();}
function ypSignContract(id){ypSyncBuys();const rec=ypBuyFor(id);if(!rec||rec.status!=='approved')return {ok:false,why:'This purchase is not ready to sign.'};const b=ypSaleBreakdown(rec.agreed,ypDepFor(rec,rec.agreed),rec);if(!b.ok)return {ok:false,why:b.why};const clock=ypReadClock();const q=b.q;G.cash-=q.payNow;Object.assign(rec,{status:'contract',price:q.price,dep:q.dep,payNow:q.payNow,atSettle:q.atSettle,loan:q.loan,loanStart:q.loan,repay:q.repay,duty:q.duty,lmi:q.lmi,lender:b.L.id,settleGameMs:ypGameMs(clock)+ypDayMs(clock)*YP_SETTLE_DAYS});log('Contract signed '+ypBuyName(id)+' @ '+ypMoneyText(q.price)+' with '+b.L.name+', '+ypMoneyText(q.payNow)+' paid now',-q.payNow);ypBuyCommit(rec,[ypBuyEvent(rec,'contract','Paid at contract '+ypMoneyText(q.payNow),clock)]);if(typeof hud==='function')hud();return {ok:true};}
function ypLoanRate(){return (typeof CFG!=='undefined'&&CFG&&Number.isFinite(+CFG.rateIP))?+CFG.rateIP:0.0672;}
function ypLoanStartAmt(b){if(!b)return 0;if(Number.isFinite(+b.loanStart)&&+b.loanStart>0)return +b.loanStart;return Math.max(0,+b.loan||0);}
function ypLoanSettleWeek(b,week){if(typeof ypDeriveSettleWeek==='function')return ypDeriveSettleWeek(b,week);if(!b)return NaN;week=week!=null?week:(typeof G!=='undefined'&&G?G.week|0:0);if(Number.isFinite(+b.settleWeek)&&(!(b.status==='owned')||(+b.settleWeek|0)<=week))return +b.settleWeek|0;if(Number.isFinite(+b.settleGameMs)&&typeof ypWeekFromGameMs==='function'){const w=ypWeekFromGameMs(+b.settleGameMs);if(Number.isFinite(w)&&(!(b.status==='owned')||(w|0)<=week))return w|0;}return NaN;}
function ypLoanWeeksPaid(b,week){week=week!=null?week:(typeof G!=='undefined'&&G?G.week|0:0);const start=ypLoanSettleWeek(b);if(!Number.isFinite(start))return 0;return Math.max(0,(week|0)-start);}
function ypAmortizeOwing(principal,repay,weeks,rate){let bal=Math.max(0,+principal||0);const pay=Math.max(0,+repay||0);const rt=rate!=null?rate:ypLoanRate();const n=Math.max(0,weeks|0);for(let i=0;i<n&&bal>0;i++){const interest=bal*rt/52;const due=Math.min(pay>0?pay:bal+interest,bal+interest);bal=Math.max(0,bal+interest-due);}return bal;}
function ypBuyRepaySched(b){const start=ypLoanStartAmt(b);if(!(start>0)&&!(b&&+b.loan>0))return 0;if(b&&+b.repay>0)return +b.repay;return typeof repayWk==='function'?repayWk(start,typeof CFG!=='undefined'?CFG.rateIP:ypLoanRate()):0;}
function ypLoanOwing(b){if(!b)return 0;if(b.status==='contract')return Math.max(0,+b.loan||ypLoanStartAmt(b));if(b.status!=='owned')return Math.max(0,+b.loan||0);if(Number.isFinite(+b.loanPaidToWeek))return Math.max(0,+b.loan||0);return ypAmortizeOwing(ypLoanStartAmt(b),ypBuyRepaySched(b),ypLoanWeeksPaid(b));}
function ypBuyRepayDue(b){if(!b||b.status!=='owned')return 0;const bal=ypLoanOwing(b);if(!(bal>0))return 0;const intr=bal*ypLoanRate()/52;return Math.min(ypBuyRepaySched(b),bal+intr);}
function ypSyncLoanBalances(opts){opts=opts||{};const charge=!!opts.charge;if(typeof ypReadBuys!=='function')return;const week=typeof G!=='undefined'&&G?G.week|0:0;const s=ypReadBuys();let changed=false;Object.values(s.buys||{}).forEach(rec=>{if(!rec||(rec.status!=='owned'&&rec.status!=='contract'))return;if(!Number.isFinite(+rec.loanStart)&&ypLoanStartAmt(rec)>0){rec.loanStart=ypLoanStartAmt(rec);changed=true;}if(rec.status==='contract')return;const sw=typeof ypDeriveSettleWeek==='function'?ypDeriveSettleWeek(rec,week):ypLoanSettleWeek(rec,week);if(Number.isFinite(sw)&&(+rec.settleWeek|0)!==(sw|0)){rec.settleWeek=sw|0;changed=true;}if(rec.status==='owned'&&Number.isFinite(sw)){const cur=Number.isFinite(+rec.settleGameMs)&&typeof ypWeekFromGameMs==='function'?ypWeekFromGameMs(+rec.settleGameMs):NaN;if(!Number.isFinite(+rec.settleGameMs)||(Number.isFinite(cur)&&cur>week)){const wm=typeof ypWeekMs==='function'?ypWeekMs(typeof ypReadClock==='function'?ypReadClock():null):(typeof CFG!=='undefined'&&CFG&&CFG.weekMs)||0;if(wm>0){rec.settleGameMs=(sw|0)*wm;changed=true;}}}const start=ypLoanStartAmt(rec);const sched=ypBuyRepaySched(rec);if(!Number.isFinite(+rec.loanPaidToWeek)){rec.loan=ypAmortizeOwing(start,sched,ypLoanWeeksPaid(rec,week));rec.loanPaidToWeek=week;changed=true;return;}if(!charge)return;while((+rec.loanPaidToWeek||0)<week){rec.loanPaidToWeek=(+rec.loanPaidToWeek||0)+1;const bal=Math.max(0,+rec.loan||0);if(!(bal>0)){changed=true;continue;}const interest=bal*ypLoanRate()/52;const pay=Math.min(sched>0?sched:bal+interest,bal+interest);rec.loan=Math.max(0,bal+interest-pay);if(typeof G!=='undefined'&&G){G.cash=(+G.cash||0)-pay;G._rep=(G._rep||0)+pay;}if(typeof ypNoteCatch==='function')ypNoteCatch('expense',pay);changed=true;}});if(changed)ypWriteBuys(s);}
function ypChargeBuyWeek(){ypSyncLoanBalances({charge:true});}
function ypWeekBudget(){const B={pay:0,tax:0,take:0,liv:0,rent:0,debt:0,credit:0,extraRent:0,boardBack:0,tenantRent:0,biz:0,invLoans:0,hold:0,build:0,props:{},loans:[],homeLoans:0,left:0,upcoming:[],bond:null,equity:[],netWorth:0,cash:0,housing:'',lease:null,applyCash:false,random:false};if(typeof G==='undefined'||!G||typeof weekMoney!=='function')return B;const m=weekMoney();const next=(G.week|0)+1;B.applyCash=!!(G.homeChosen||G.clockOn);B.housing=typeof housing==='function'?housing():'';B.cash=+G.cash||0;if(B.applyCash){B.pay=m.earn;B.tax=m.tax;B.take=m.take;B.liv=m.liv;B.rent=m.rent;B.debt=m.debt;}
 const rentals=(ypReadStock().rentals||[]);const covered=!!(G.homeChosen&&G.lease&&!G.lease.broken);const active=rentals.find(r=>r&&r.status==='active'&&r.bondCharged)||null;
 if(covered){B.lease={id:null,rent:Math.round(+G.lease.rent||0),months:G.lease.months,end:G.lease.end,m2m:!!G.lease.m2m};const mine=rentals.find(r=>r&&r.status==='active'&&r.bondCharged&&(r.footprintId||r.id)===G.lease.id);if(mine)B.lease.id=mine.id;rentals.forEach(r=>{if(r.status!=='active'||!r.bondCharged||!r.advancePaid||(r.footprintId||r.id)!==G.lease.id)return;const wk=next-(r.startWeek|0);if(wk>=1&&wk<=2&&!(r.advanceUsed>=wk))B.credit+=Math.round(+G.lease.rent||0);});}
 else{rentals.forEach(r=>{if(r.status!=='active'||!r.bondCharged)return;const st=r.startWeek|0,last=r.lastChargedWeek==null?st:r.lastChargedWeek|0;if(next<=last||next<=st)return;B.extraRent+=(next-last)*Math.round(+r.weeklyRent||0);});if(B.extraRent>0&&G.clockOn&&!G.homeChosen&&!(G.lease&&G.lease.id)&&typeof NOHOME_BOARD==='number')B.boardBack=NOHOME_BOARD;}
 if(active)B.bond={id:active.id,amount:Math.round(+active.bondPaid||+active.bond||0)};
 try{for(const[id,p]of allProps()){if(p.status==='settling'){B.upcoming.push({id:null,name:typeof pname==='function'?pname(id):'',amount:+p.atSettle||0,when:'Game week '+(p.settleWk|0),soon:next>=p.settleWk});continue;}const d=p.dev;if(d&&d.stage==='build'){const total=d.cost+(d.biz?bizSetup(d.biz):0),draw=total/d.weeks,fromLoan=Math.min(draw*(d.clvr??CFG.constrLVR)*(d.loanCap?1:0),d.loanCap-d.drawn);const capex=draw-fromLoan;B.build+=capex;ypBudgetProp(B,id).build+=capex;}if(!(d&&d.stage!=='done')){const r=weeklyRent(id);if(r>0&&!(p.vacant>0)){const net=r*(1-mgmt(id));B.tenantRent+=net;ypBudgetProp(B,id).rentIn+=net;}if(d&&d.biz){const pr=bizProfit(d);B.biz+=pr;ypBudgetProp(B,id).biz+=pr;B.random=true;}}if(p.loan>0){const intr=p.loan*(p.io?CFG.rateIO:CFG.rateIP)/52;const inv=p.io?intr:Math.min(p.repay,p.loan+intr);B.invLoans+=inv;ypBudgetProp(B,id).invLoan+=inv;}const hold=holdWk(id)+(p.prot?protFee(p.prot):0);B.hold+=hold;ypBudgetProp(B,id).hold+=hold;B.random=true;B.equity.push({id:null,name:typeof pname==='function'?pname(id):'',value:value(id),loan:+p.loan||0});}}catch(e){}
 Object.values(ypReadBuys().buys).forEach(b=>{if(b.status==='owned'){const owing=ypLoanOwing(b);const rep=ypBuyRepayDue(b);if(rep>0){B.loans.push({id:b.id,rep,loan:owing});ypBudgetProp(B,b.id).homeLoan+=rep;ypBudgetProp(B,b.id).loan=owing;}B.equity.push({id:b.id,value:+b.estimate||0,loan:owing});}else if(b.status==='contract'){B.upcoming.push({id:b.id,amount:+b.atSettle||0,when:Number.isFinite(+b.settleGameMs)&&typeof ypWallAt==='function'?ypRealDateLabel(ypWallAt(+b.settleGameMs)):'',loan:ypLoanOwing(b),repay:ypBuyRepaySched(b)});B.equity.push({id:b.id,value:+b.payNow||0,loan:0,contract:true});}});
 B.homeLoans=B.loans.reduce((t,l)=>t+l.rep,0);
 B.left=(B.applyCash?B.take-B.rent-B.liv-B.debt:0)+B.credit-B.extraRent+B.boardBack+B.tenantRent+B.biz-B.invLoans-B.hold-B.build-B.homeLoans;
 B.netWorth=typeof netWorth==='function'?netWorth():B.cash;return B;}
function ypWeeklyRepay(b){return ypBuyRepaySched(b);}/* live at the game rate (6.72%) over 30 years, same figure as My Properties */
function ypBuyHeld(){return Object.values(ypReadBuys().buys).filter(b=>b.status==='contract'||b.status==='owned');}
function ypBuyDebt(){return ypBuyHeld().reduce((t,b)=>t+ypLoanOwing(b),0);}
function ypBuyEquity(){return ypBuyHeld().reduce((t,b)=>t+(b.status==='contract'?(+b.payNow||0):(+b.estimate||0)-ypLoanOwing(b)),0);}
function ypBuyAmt(n){const v=Math.round(Number(n));if(!Number.isFinite(v))return '';if(v<0)return 'None';return typeof fmtK==='function'?fmtK(v):ypMoneyText(v);}
function ypOwnStatus(b){
 const owned=b.status==='owned';
 const week=typeof ypLoanSettleWeek==='function'?ypLoanSettleWeek(b):(Number.isFinite(+b.settleGameMs)&&typeof ypWeekFromGameMs==='function'?ypWeekFromGameMs(+b.settleGameMs):NaN);
 const keys=Number.isFinite(week)&&(typeof ypGameWeekLabel==='function'?'Keys '+ypGameWeekLabel(week):'Keys Week '+week);
 if(!owned)return Number.isFinite(week)&&(typeof ypGameWeekLabel==='function'?'Settles '+ypGameWeekLabel(week):'Settles Week '+week)||'Under contract';
 const live=typeof ypLiveOwnedId==='function'&&ypLiveOwnedId()===b.id;
 if(live)return 'You live here';
 if(b.intent&&b.intent!=='live')return 'Rented out';
 return keys||'You own this';
}
function ypBuyRows(){const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);let waiting=false;ypSyncLoanBalances();const rows=ypBuyHeld().map(b=>{const code=ypPropertyIdCode(b.id);const coded=/^[A-Z]{3}-\d{4}$/.test(code);const sub=ypOfficialSuburb(b.id);if(!coded||!sub)waiting=true;const owned=b.status==='owned';const price=+b.price||+b.agreed||+b.estimate||0;const value=+b.estimate||price;const loan=ypLoanOwing(b);const equity=owned?value-loan:(+b.payNow||0);const type=YP_FEED_TYPES[b.tone]||'Building';const status=ypOwnStatus(b);const repay=loan>0?ypWeeklyRepay(b):0;const loanLabel=loan>0?ypBuyAmt(loan):'Owned outright';const figs=[{lab:'Value',val:ypBuyAmt(value)},{lab:'Amount owing',val:loanLabel},{lab:'Equity',val:ypBuyAmt(equity)}].map(f=>`<div class="yp-own-fig"><dt>${esc(f.lab)}</dt><dd>${esc(f.val)}</dd></div>`).join('');const repayLine=repay>0?`<p class="yp-own-repay">Loan repayment ${ypMoneyText(repay)} a week</p>`:'';return `<article class="yp-own-card yp-own-row" data-yp-own="${esc(b.id)}" role="button" tabindex="0" onclick="ypGameUI().close();ypOpenBuy('${b.id}')"><div class="yp-own-head"><div class="yp-own-sub">${esc(sub||'Your property')}</div><span class="yp-own-go" aria-hidden="true">›</span></div><p class="yp-own-id">Property ID: ${esc(coded?code:'…')}</p><p class="yp-own-meta"><span class="yp-own-type">${esc(type)}</span> ${esc(status)}</p><dl class="yp-own-figs">${figs}</dl>${repayLine}</article>`;});if(waiting){ypCodeShard('localities');ypBuyHeld().forEach(b=>{const g=ypCodeBuilding(b.id);if(g)ypCodeShard(g.slice(4,6));});ypOwnRowsWait=true;}return rows;}
/* My Properties is plain HTML, so when the code and suburb data arrive, draw it again (old saves showed 'your property, Bundaberg Region' until then) */
let ypOwnRowsWait=false;document.addEventListener('yp-codes',()=>{if(!ypOwnRowsWait)return;ypOwnRowsWait=false;if(document.querySelector('.yp-own-row')&&ypGameUI())setTimeout(()=>{if(document.querySelector('.yp-own-row'))ypGameUI().mine();},0);});
function ypOpenBuy(id){const rec=ypBuyFor(id);if(rec)ypOpenSaleDetail(ypBuyFeature(rec));}
/* Deposit the player chooses: at least the lender minimum (5%), at most what Bank can cover after duty, mortgage insurance and legals. Stored on the purchase as a % (quick buttons) or dollars (typed). */
function ypDepMin(price){return Math.ceil(price*curLender().min);}
/* cash already promised to purchases that are still settling is kept aside */
function ypBuySettling(){return Object.values(ypReadBuys().buys).filter(b=>b.status==='contract');}
function ypFreeCash(){return (+G.cash||0)-ypBuySettling().reduce((t,b)=>t+ypSettleDue(b),0);}
function ypDepMax(price){const cash=ypFreeCash();if(quote(price,0,price,null).cash<=cash)return price;for(let d=Math.floor(price/1000)*1000;d>0;d-=1000)if(quote(price,0,d,null).cash<=cash)return d;return 0;}
function ypDepPick(choice,price){const d=choice&&choice.pct?Math.ceil(price*choice.pct):Math.round(+(choice&&choice.amt)||0);return Math.min(price,Math.max(ypDepMin(price),d));}
function ypDepDefault(price){return price>0&&ypDepMax(price)>=Math.ceil(price*.2)?{pct:.2}:{pct:curLender().min};}
function ypDepFor(rec,price){return ypDepPick(rec&&(rec.depPct?{pct:rec.depPct}:{amt:rec.depAmt}),price);}
function ypDepLoanOk(price,d,rec){const q=quote(price,0,d,null);if(q.loan<=0)return ypFreeCash()>=q.cash;const p=typeof ypLoanPower==='function'?ypLoanPower(ypLoanOptsFromRec(rec)):null;if(p)return q.loan<=p.power&&ypFreeCash()>=q.cash;return loanCheck(q.loan,0,0,ypFreeCash()-q.payNow).ok;}
/* smallest deposit (rounded up to $1,000) the bank approves and Bank can pay for, or null */
function ypDepNeeded(price,rec){const cash=ypFreeCash(),lo0=ypDepMin(price);let d=lo0;if(!ypDepLoanOk(price,lo0,rec)){let lo=lo0,hi=price;if(!ypDepLoanOk(price,hi,rec))return null;while(hi-lo>1){const m=Math.floor((lo+hi)/2);if(ypDepLoanOk(price,m,rec))hi=m;else lo=m;}d=hi;}d=Math.min(price,Math.ceil(d/1000)*1000);for(const c of [d,Math.max(d,Math.ceil(price*.2/1000)*1000)])if(quote(price,0,c,null).cash<=cash&&ypDepLoanOk(price,c,rec))return c;return null;}
function ypSaleBreakdown(price,dep,rec){const L=curLender();if(dep==null)dep=ypDepMin(price);const q=quote(price,0,dep,null);const cash=ypFreeCash();const held=ypBuySettling();const keep=(+G.cash||0)-cash;const opts=ypLoanOptsFromRec(rec);const pwr=typeof ypLoanPower==='function'?ypLoanPower(opts):null;const lc=typeof loanCheck==='function'?loanCheck(q.loan,opts.rentInWk||0,0,cash-q.payNow):{ok:true,b:{power:0}};const power=pwr?pwr.power:lc.b.power;const loanOk=q.loan<=0||q.loan<=power;const M=ypMoneyText;const why=[];if(held.length&&(cash<q.cash||!loanOk))why.push('You already have '+held.map(h=>ypBuyName(h.id)+' settling (loan '+M(h.loan)+', '+M(ypSettleDue(h))+' still to pay at settlement)').join(' and ')+'.');if(cash<q.cash)why.push((keep>0?'After keeping '+M(keep)+' for that, you have '+M(Math.max(0,cash))+' free in the bank':'You have '+M(cash)+' in the bank')+', but you need '+M(q.cash)+' for the deposit and costs.');if(!loanOk)why.push(power<=0?"The bank can't lend you more right now because you would spend more than you earn each week.":(held.length?'With that, the bank can lend you up to ':'The bank will lend you up to ')+M(power)+', but this loan is '+M(q.loan)+'.');const ok=!why.length;const need=ok?null:ypDepNeeded(price,rec);const fix=ok?'':need!=null&&need>dep?'A deposit of '+M(need)+' or more would be approved.':power<=0?'Cut costs or earn more, then check again. Or try a cheaper home you can buy with cash.':'Even your whole bank is not enough here. Try a lower offer or a cheaper home.';return {L,q,cash,power,weekly:q.repay,monthly:q.repay*52/12,ok,need,why:why.join(' '),fix,verdict:ok?'The bank should approve this.':'The bank would say no. '+why.join(' ')+' '+fix,intent:opts.intent||''};}
/* Shared deposit chooser for Step 1 and the declined finance step. price() gives the current price, onChange() redraws the numbers. */
function ypDepositPicker(price,choice,onChange){const box=document.createElement('div');box.className='yp-dep';box.id='yp-dep';const lab=document.createElement('p');lab.className='yp-dep-lab';lab.textContent='Your deposit';const row=document.createElement('div');row.className='yp-dep-row';const opts=[.05,.1,.2,1].map(p=>{const b=document.createElement('button');b.type='button';b.className='yp-dep-opt';b.id=p===1?'yp-dep-cash':'yp-dep-'+Math.round(p*100);b.textContent=p===1?'Cash':Math.round(p*100)+'%';b.addEventListener('click',()=>{choice={pct:p};draw(true);});row.appendChild(b);return [p,b];});const input=document.createElement('input');input.type='number';input.id='yp-dep-amount';input.inputMode='numeric';input.step='1000';input.setAttribute('aria-label','Deposit in dollars');input.addEventListener('input',()=>{choice={amt:Math.round(+input.value)||0};draw(false);});input.addEventListener('change',()=>draw(true));const lim=document.createElement('p');lim.className='yp-hint yp-dep-lim';box.append(lab,row,input,lim);const get=()=>{const pr=price();if(!(pr>0))return 0;const lo=ypDepMin(pr),hi=Math.max(lo,ypDepMax(pr));return Math.min(hi,ypDepPick(choice,pr));};const draw=fill=>{const pr=price();if(!(pr>0))return;const lo=ypDepMin(pr),hi=ypDepMax(pr),d=get();if(fill!==false)input.value=String(d);input.min=String(lo);if(hi>=lo)input.max=String(hi);opts.forEach(([p,b])=>{const v=Math.ceil(pr*p);b.disabled=v>hi;b.setAttribute('aria-pressed',String(Math.abs(d-v)<1&&!!choice&&(choice.pct===p||Math.abs((choice.amt||0)-v)<1)));});lim.textContent=hi<lo?'Your Bank cannot cover the minimum '+ypMoneyText(lo)+' (5%) plus costs.':hi>=pr?'From '+ypMoneyText(lo)+' (5%) up to the full price. Cash means no loan.':'From '+ypMoneyText(lo)+' (5%) up to '+ypMoneyText(hi)+', the most your Bank can cover after costs'+(ypBuySettling().length?' and your other settlement.':'.');if(onChange)onChange();};return {el:box,get,choice:()=>{const d=get(),pr=price();return choice&&choice.pct&&Math.abs(d-Math.ceil(pr*choice.pct))<1?{pct:choice.pct}:{amt:d};},set:c=>{choice=c;draw(true);},draw};}
/* live money rows for a price and deposit; used by Step 1, the declined step and Sign Contract */
function ypDepRows(b){const M=ypMoneyText,q=b.q;return [{label:'Deposit',hint:(Math.round(q.dep/q.price*1000)/10)+'% of the price',value:M(q.dep),id:'yp-q-dep'},{label:'Loan amount',hint:q.loan>0?'Price minus deposit':'Cash buy, no loan',value:M(q.loan),id:'yp-q-loan'},{label:'Weekly repayment',hint:(CFG.rateIP*100).toFixed(2)+'% over '+CFG.termY+' years',value:M(q.repay),id:'yp-q-rep'},{label:'Pay when you sign',hint:'Deposit, up to 10%',value:M(q.payNow),id:'yp-q-now'},{group:'Total due at settlement',hint:'Rest of deposit and costs',kind:'due',items:ypQuoteSettleItems(q),total:q.atSettle,valId:'yp-q-settle'}];}
function ypRetryFinance(id,choice){const clock=ypReadClock();const rec=ypBuyFor(id);if(!rec||rec.status!=='declined')return;delete rec.depPct;delete rec.depAmt;if(choice.pct)rec.depPct=choice.pct;else rec.depAmt=choice.amt;delete rec.declineWhy;delete rec.needDep;const events=[ypBuyEvent(rec,'financeApplied','Deposit '+ypMoneyText(ypDepFor(rec,rec.agreed)),clock)];ypStartFinance(rec,clock,events);ypBuyCommit(rec,events);}
function ypSaleRows(b){const pct=Math.round(b.q.dep/b.q.price*1000)/10;const costs=[{label:'Deposit ('+pct+'%)',amount:b.q.dep,hint:'You choose it when you buy'},{label:'Stamp duty',amount:b.q.duty,hint:'QLD transfer duty'}];if(b.q.lmi)costs.push({label:'Mortgage insurance',amount:b.q.lmi,hint:'Loan is over 80% of the price'});costs.push({label:'Conveyancing',amount:b.q.legal,hint:'Legal fees'});if(b.q.ins)costs.push({label:'Property insurance',amount:b.q.ins,hint:'First year'});return [{group:'Total cash needed',hint:'Deposit plus costs',kind:'due',items:costs,total:b.q.cash},{label:'In the bank',amount:b.cash,hint:ypBuySettling().length?'Free after your other settlement':'Your balance now'},{label:'Loan amount',amount:b.q.loan,hint:'Price minus deposit'},{label:'Weekly repayment',amount:b.weekly,hint:(CFG.rateIP*100).toFixed(2)+'% over '+CFG.termY+' years'},{label:'Your borrowing power',amount:b.power,hint:'Game bank today'}];}
function ypOpenSaleDetail(feature){const props=feature&&feature.properties||{};const id=props.gameId;ypSyncBuys();const rec=ypBuyFor(id);const clock=ypReadClock();ypExclusive('yp-sale-detail');document.getElementById('yp-sale-detail')?.remove();const st=rec?rec.status:'open';const held=st==='contract'||st==='owned';const agreed=['finance-choice','finance-pending','approved','contract','owned'].includes(st);const price=agreed?rec.agreed:props.estimate;const b=ypSaleBreakdown(price,ypDepFor(rec,price),rec);const area=ypOuterRings(feature.geometry).reduce((t,r)=>t+ypRingAreaM2(r),0);const suburb=ypOfficialSuburb(id);const facts=[{label:'Type',amount:YP_FEED_TYPES[props.tone]||'Building'}];if(area>0)facts.push({label:'Footprint',amount:Math.round(area).toLocaleString('en-AU')+' m²'});const settleGroup={group:st==='owned'?'Total paid at settlement':'Total due at settlement',hint:'Rest of deposit, duty, LMI, legals',kind:'due',items:ypRecSettleItems(rec),total:ypSettleDue(rec)};const flow=held?[{label:'Paid at contract',amount:rec.payNow,hint:'Part of the deposit'},settleGroup,{label:st==='owned'?'Amount borrowed':'Loan amount',amount:st==='owned'?ypLoanStartAmt(rec):rec.loan,hint:st==='owned'?'Original loan':'With '+((LENDERS.find(l=>l.id===rec.lender)||b.L).name)},st==='owned'?{label:'Amount owing',amount:ypLoanOwing(rec),hint:'With '+((LENDERS.find(l=>l.id===rec.lender)||b.L).name)}:null,rec.loan>0?{label:'Weekly repayment',amount:ypWeeklyRepay(rec),hint:(CFG.rateIP*100).toFixed(2)+'% over '+CFG.termY+' years'}:null]:ypSaleRows(b);const ypMineInProgress=!!rec&&['negotiating','finance-choice','finance-pending','approved','contract'].includes(st);const left=(at,unit)=>Math.max(1,Math.ceil((at-ypGameMs(clock))/unit));const status={'finance-choice':'The seller accepted your offer. Tell the bank whether you will live here or rent it out.', 'finance-pending':'Your finance application is with '+b.L.name+'. About '+left(rec&&rec.approveGameMs,ypHourMs(clock))+' game hour left.',approved:'',declined:'Your finance was declined. '+(rec&&rec.declineWhy||'')+' Nothing was charged.'+(st==='declined'&&rec&&rec.agreed&&ypDepNeeded(rec.agreed,rec)!=null?' The smallest deposit the bank would approve is '+ypMoneyText(ypDepNeeded(rec.agreed,rec))+'.':''),ended:ypCanOffer(rec,clock)?'The seller ended talks last time. You can make a new offer.':'The seller ended talks. You can make a new offer after '+YP_NEGOTIATION.cooldownDays+' game day.',walked:'You walked away from this offer. You can make a new offer any time.',contract:'Under contract. Settlement in about '+left(rec&&rec.settleGameMs,ypDayMs(clock))+' game days.',owned:'You own this property.'}[st];const panel=document.createElement('div');panel.id='yp-sale-detail';panel.setAttribute('role','dialog');panel.setAttribute('aria-labelledby','yp-listing-title');const card=document.createElement('div');ypMountListing(card,{codeFor:id,approval:st==='approved'?'Your finance has been approved.':'',money:[{label:agreed?'Agreed price':'Game estimate',amount:ypMoneyText(price),primary:true}].concat(facts),place:suburb,flow,status:status==null?b.verdict:status,limitation:(held||ypMineInProgress)?'A game price is not a real valuation.':'No player owns this property, so it is for sale. Make an offer to the seller\'s agent. A game price is not a real valuation.'});const shut=()=>panel.remove();if(ypMineInProgress){try{const it=ypPendingBuyItem(rec);const line=document.createElement('p');line.className='yp-status yp-sale-progress';line.id='yp-sale-progress';const bold=document.createElement('b');bold.textContent=it.title+'. ';line.append(bold,it.next+' ');const go=document.createElement('a');go.href='#';go.className='yp-resume-link';go.id='yp-sale-resume';go.textContent='Continue';go.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();panel.remove();ypResumeBuy(id);});line.appendChild(go);const old=card.querySelector('.yp-status');if(old)old.replaceWith(line);else{const lim=card.querySelector('.yp-limit');if(lim)lim.before(line);else card.appendChild(line);}}catch(e){}}ypHeaderDismiss(card.querySelector('.hwh'),shut);const step=['negotiating','finance-choice','finance-pending','approved','declined','contract'].includes(st)?()=>ypResumeBuy(id):ypCanOffer(rec,clock)?()=>ypOpenBuyStep(id,'offer',feature):null;if(st!=='owned'){const buy=document.createElement('button');buy.type='button';buy.className='hwb';buy.id='yp-sale-buy';buy.textContent={negotiating:'Continue offer','finance-choice':'Choose how you will use this home','finance-pending':'See finance check',approved:'Sign contract',declined:'Try again with a bigger deposit',contract:'See settlement'}[st]||'Buy this property';buy.disabled=!step;if(step)buy.addEventListener('click',step);card.appendChild(buy);}if(held||rec){const show=document.createElement('button');show.type='button';show.className='hwx yp-show-map';show.id='yp-sale-showmap';show.textContent='Show on map';show.addEventListener('click',()=>ypOpenProperty(id,{card:false}));card.append(show);}const back=document.createElement('button');back.type='button';back.className='hwx';back.textContent='Back';back.addEventListener('click',shut);card.append(back);panel.addEventListener('click',e=>{if(e.target===panel)shut();});panel.appendChild(card);document.body.appendChild(panel);if(!suburb&&id)Promise.all([ypCodeShard(id.slice(4,6)),ypCodeShard('localities')]).then(()=>{if(panel.isConnected&&ypOfficialSuburb(id))ypOpenSaleDetail(feature);});}
/* One small centred card per buying step, over the agent office background (#yp-agent-bg). */
function ypResumeBuy(id){const rec=ypBuyFor(id);const step=rec&&{negotiating:'reply','finance-choice':'finance','finance-pending':'finance',approved:'confirm',declined:'finance',contract:'settle',owned:'settle'}[rec.status];if(step)ypOpenBuyStep(id,step);else ypOpenBuy(id);}/* one place that knows which step a purchase is at: bell, Pending Offers and the property card all use it */
function ypOpenBuyStep(id,step,feature,note){ypSyncBuys();const rec=ypBuyFor(id);feature=feature||(rec&&ypBuyFeature(rec));if(!feature)return;if(step==='reply'&&rec){ypOpenBuyChat(id,feature);return;}if(step==='confirm'&&(!rec||rec.status!=='approved')){ypResumeBuy(id);return;}ypExclusive('yp-apply-review');['yp-apply-review','yp-sale-detail'].forEach(k=>document.getElementById(k)?.remove());const panel=document.createElement('div');panel.id='yp-apply-review';panel.className='yp-steps';panel.dataset.step=step;panel.setAttribute('role','dialog');panel.setAttribute('aria-labelledby','yp-review-title');const card=document.createElement('div');card.className='card yp-listing yp-step';const shut=()=>panel.remove();const titles={offer:'Make an Offer',reply:'Agent\'s Reply',finance:'Finance Check',confirm:'Sign Contract',settle:'Settlement'};const order=['offer','reply','finance','confirm','settle'];card.appendChild(ypCardHeader({kicker:'Step '+(order.indexOf(step)+1)+' of '+order.length,title:titles[step],titleId:'yp-review-title',onClose:shut}));const pid=document.createElement('p');pid.className='yp-step-id';pid.appendChild(ypPropertyIdLabel(id));card.appendChild(pid);const text=(t,cls)=>{const p=document.createElement('p');if(cls)p.className=cls;p.textContent=t;card.appendChild(p);return p;};const btn=(label,cls,fn,bid)=>{const b=document.createElement('button');b.type='button';b.className=cls;b.textContent=label;if(bid)b.id=bid;b.addEventListener('click',fn);card.appendChild(b);return b;};const est=feature.properties.estimate;const clock=ypReadClock();const M=ypMoneyText;
 if(step==='offer'){const nego=rec&&rec.status==='negotiating';const input=document.createElement('input');input.type='number';input.id='yp-offer-amount';input.inputMode='numeric';input.step='1000';input.min='1';input.value=String(nego?Math.min(rec.ask,rec.lastOffer+YP_NEGOTIATION.roundTo):est);if(nego)input.min=String(rec.lastOffer+1);input.setAttribute('aria-label','Your offer in dollars');text(nego?'The seller is asking '+M(rec.ask)+'. Your last offer was '+M(rec.lastOffer)+'. Your new offer must be higher.':'Game estimate '+M(est)+'. Type your offer, then pick your deposit. Nothing is charged yet.');card.appendChild(input);const offerV=()=>Math.round(+input.value);const host=document.createElement('div');const verdict=document.createElement('p');verdict.className='yp-status';verdict.id='yp-offer-verdict';const fixBtn=document.createElement('button');fixBtn.type='button';fixBtn.className='yp-pill';fixBtn.id='yp-dep-fix';const render=()=>{const v=offerV();if(!(v>0)){host.replaceChildren();verdict.textContent='Enter an amount in whole dollars.';fixBtn.hidden=true;return;}const b=ypSaleBreakdown(v,dep.get(),rec);host.replaceChildren(ypFlow(ypDepRows(b)));verdict.textContent=b.verdict;fixBtn.hidden=!(b.need!=null&&b.need>b.q.dep);if(!fixBtn.hidden)fixBtn.textContent='Use a '+M(b.need)+' deposit';};const dep=ypDepositPicker(offerV,rec&&(rec.depPct?{pct:rec.depPct}:rec.depAmt?{amt:rec.depAmt}:null)||ypDepDefault(offerV()),render);fixBtn.addEventListener('click',()=>{const v=offerV();const n=ypDepNeeded(v);if(n!=null)dep.set({amt:n});});card.append(dep.el,verdict,fixBtn,host);input.addEventListener('input',()=>dep.draw(true));dep.draw(true);const err=text(note||'','yp-status');err.id='yp-offer-error';btn('Send offer','hwb',()=>{const v=offerV();if(!(v>0)){err.textContent='Enter an amount in whole dollars.';return;}const r=ypSubmitOffer(feature,v,dep.choice());if(!r.ok){err.textContent=r.reason==='higher'?'Your new offer must be higher than '+M(rec.lastOffer)+'.':'An offer cannot be made right now.';return;}ypOpenBuyStep(id,'reply',feature);},'yp-offer-next');btn('Cancel','hwx',shut);}
 else if(step==='finance'){if(rec.status==='finance-choice'||(rec.status!=='approved'&&rec.status!=='declined'&&rec.status!=='finance-pending'&&!rec.intent)){
  text('The seller accepted your offer. How will you use this home? The bank uses your answer to check the loan.');
  const live=btn("I'll live here",'hwb',()=>{rec.intent='live';const clock=ypReadClock();const events=[ypBuyEvent(rec,'financeApplied','You will live here',clock)];ypStartFinance(rec,clock,events);ypBuyCommit(rec,events);ypOpenBuyStep(id,'finance',feature);},'yp-intent-live');
  text(ypActivePlayerLease()?'The bank still counts the rent you pay now, because you keep paying it until a new tenant moves in.':'The bank still counts the rent you pay now.','yp-limit');
  const inv=btn("I'll rent it out",'hwb',()=>{rec.intent='invest';const clock=ypReadClock();const events=[ypBuyEvent(rec,'financeApplied','You will rent it out',clock)];ypStartFinance(rec,clock,events);ypBuyCommit(rec,events);ypOpenBuyStep(id,'finance',feature);},'yp-intent-invest');
 const est=ypSaleRentEstimate(id);if(est)text('The bank would count 80% of the estimated rent of '+M(est)+' a week.','yp-limit');else text('This home has no rent estimate in the game, so the bank will not count rental income.','yp-limit');
  btn('Close','hwx',shut,'yp-finance-close');}
 else {const b=ypSaleBreakdown(rec.agreed,ypDepFor(rec,rec.agreed),rec);if(rec.status==='approved'){text(b.q.loan>0?'The bank approved your loan.':'No loan needed. You are paying cash.','yp-approval');card.appendChild(ypFlow([{label:'Agreed price',value:M(rec.agreed)},{label:'Deposit',hint:(Math.round(b.q.dep/b.q.price*1000)/10)+'% of the price',value:M(b.q.dep)},{label:'Loan amount',hint:b.L.name,value:M(b.q.loan)},{label:'Weekly repayment',hint:(CFG.rateIP*100).toFixed(2)+'% over '+CFG.termY+' years',value:M(b.weekly)}]));text('Next you sign the contract and pay the deposit.');btn('Next: sign contract','hwb',()=>ypOpenBuyStep(id,'confirm',feature),'yp-finance-next');}
  else if(rec.status==='declined'){text('The bank said no to this loan.','yp-approval');const now=ypSaleBreakdown(rec.agreed,ypDepFor(rec,rec.agreed),rec);const why=text((now.ok?'Your Bank and this deposit pass the check now. Tap Try again to apply.':now.why)+' Nothing was charged.');why.id='yp-decline-why';const need=now.ok?ypDepFor(rec,rec.agreed):now.need;if(need!=null){const host=document.createElement('div');const verdict=document.createElement('p');verdict.className='yp-status';verdict.id='yp-offer-verdict';let go;const render=()=>{const b2=ypSaleBreakdown(rec.agreed,dep.get(),rec);host.replaceChildren(ypFlow([{label:'Smallest deposit the bank approves',value:M(need),id:'yp-need-dep'}].concat(ypDepRows(b2))));verdict.textContent=b2.verdict;if(go){go.textContent='Try again with '+M(b2.q.dep)+' deposit';go.disabled=!b2.ok;}};const dep=ypDepositPicker(()=>rec.agreed,{amt:need},render);card.append(dep.el,verdict,host);go=btn('','hwb',()=>{ypRetryFinance(id,dep.choice());ypOpenBuyStep(id,'finance',feature);},'yp-finance-redeposit');dep.draw(true);}else text('Even with your whole Bank as a deposit the bank would say no. Try a lower offer or a cheaper home.');btn('Make a new offer','hwx',()=>ypOpenBuyStep(id,'offer',feature),'yp-finance-retry');btn('Close','hwx',shut);}
  else{text('The bank is checking your loan.','yp-approval');const left=text('','yp-status');left.id='yp-finance-left';const bar=document.createElement('div');bar.className='yp-meter';const fill=document.createElement('span');bar.appendChild(fill);card.appendChild(bar);card.appendChild(ypFlow([{label:'Agreed price',value:M(rec.agreed)},{label:'Deposit',value:M(b.q.dep)},{label:'Loan amount',hint:b.L.name,value:M(b.q.loan)}]));text('You can close this. The bell will tell you when the bank decides.','yp-limit');btn('Close','hwx',shut,'yp-finance-close');const total=ypHourMs(clock);const draw=()=>{const c=ypReadClock();const ms=Math.max(0,Math.min(rec.approveGameMs-ypGameMs(c),rec.approveAt-c.wall));left.textContent=ypCap(ypRealLeft(ms))+' left.';fill.style.width=Math.min(100,Math.max(4,Math.round((1-ms/total)*100)))+'%';};draw();const tick=setInterval(()=>{if(!panel.isConnected)return clearInterval(tick);ypSyncBuys();if((ypBuyFor(id)||{}).status!=='finance-pending'){clearInterval(tick);ypOpenBuyStep(id,'finance',feature);return;}draw();},1000);}}}
 else if(step==='confirm'){const b=ypSaleBreakdown(rec.agreed,ypDepFor(rec,rec.agreed),rec);text('Sign the contract and pay the deposit now. The rest is paid at settlement.');card.appendChild(ypFlow([{label:'Agreed price',value:M(b.q.price)},{label:'Building and pest',hint:'Inspection',value:'Passed'},{label:'Deposit',hint:(Math.round(b.q.dep/b.q.price*1000)/10)+'% of the price',value:M(b.q.dep)},{label:'Loan amount',hint:b.L.name,value:M(b.q.loan)},{label:'Weekly repayment',hint:(CFG.rateIP*100).toFixed(2)+'% over '+CFG.termY+' years',value:M(b.q.repay)},{label:'Pay now',hint:'Deposit, paid when you sign',value:M(b.q.payNow)},{label:'Bank after signing',hint:'Your balance minus the deposit',value:M((+G.cash||0)-b.q.payNow)},{group:'Total due at settlement',hint:'In '+YP_SETTLE_DAYS+' game days',kind:'due',items:ypQuoteSettleItems(b.q),total:b.q.atSettle}]));text('In real life you would have 5 business days to change your mind. In the game, signing is final.','yp-limit');const err=text(note||'','yp-status');btn('Sign and pay '+M(b.q.payNow),'hwb',()=>{const r=ypSignContract(id);if(r.ok)ypOpenBuyStep(id,'settle',feature);else err.textContent=r.why+' Nothing was charged.';},'yp-buy-sign');btn('Not yet','hwx',shut);}
 else if(rec.status==='owned'){text('Keys collected. You own this property.','yp-approval');card.appendChild(ypFlow([{label:'Price paid',value:M(rec.price)},{group:'Total paid at settlement',hint:'Taken from your bank',kind:'due',items:ypRecSettleItems(rec),total:ypSettleDue(rec)},{label:'Amount borrowed',hint:'Original loan',value:M(ypLoanStartAmt(rec))},{label:'Amount owing',hint:(LENDERS.find(l=>l.id===rec.lender)||curLender()).name,value:M(ypLoanOwing(rec))},{label:'Weekly repayment',hint:(CFG.rateIP*100).toFixed(2)+'% over '+CFG.termY+' years',value:M(rec.repay)}]));text('You will find it in Property Owned.','yp-limit');btn('Done','hwb',shut,'yp-buy-done');}
 else{const days=Math.max(1,Math.ceil((rec.settleGameMs-ypGameMs(clock))/ypDayMs(clock)));const rest=rec.dep-rec.payNow,legal=rec.atSettle-rest-rec.duty-(rec.lmi||0);text('You\'re under contract.','yp-approval');text('Settles in '+days+' game days. Here is what you pay then.');card.appendChild(ypFlow([{label:'Paid at contract',hint:'Deposit',value:M(rec.payNow)},{group:'Total due at settlement',hint:'Taken from your bank',kind:'due',items:ypRecSettleItems(rec),total:ypSettleDue(rec)},{label:'Loan',hint:(LENDERS.find(l=>l.id===rec.lender)||curLender()).name,value:M(rec.loan)}]));text('On settlement day the bell tells you, and you get the keys.','yp-limit');if(rec.intent==='live'&&ypActivePlayerLease())text('You keep paying rent on your current lease until a new tenant moves in. After settlement you can pay out the lease if you want to end it sooner.','yp-limit');btn('Done','hwb',shut,'yp-buy-done');}
 panel.addEventListener('click',e=>{if(e.target===panel)shut();});panel.appendChild(card);document.body.appendChild(panel);ypAgentClip(rec&&rec.status==='negotiating'?'counter':'office');}
const YP_AGENT_CLIPS={office:'agent-office',counter:'agent-counter',talk:'agent-counter-talk',rentCall:'rent-call',rentInspect:'rent-inspect',rentKeys:'rent-keys'};YP_AGENT_POSTERS={talk:'agent-counter'};/* video per moment of the buying flow; drop a new counter clip into assets/ and name it here */
function ypAgentClip(kind,onDone){const bg=document.getElementById('yp-agent-bg');const name=YP_AGENT_CLIPS[kind]||YP_AGENT_CLIPS.office;if(!bg){if(onDone)onDone();return;}const once=!!onDone;const pic=YP_AGENT_POSTERS[kind]||name;bg.loop=!once;bg.muted=!once;bg.onended=null;if(bg.dataset.clip!==name){bg.dataset.clip=name;bg.poster='assets/'+pic+'.webp';bg.src='assets/'+name+'.mp4';bg.style.backgroundImage='url(assets/'+pic+'.webp)';}else if(once)bg.currentTime=0;if(!once){bg.play().catch(()=>{});return;}let fired=false;const done=()=>{if(fired)return;fired=true;clearTimeout(t);bg.onended=null;onDone();};const t=setTimeout(done,9000);bg.onended=done;bg.play().catch(()=>{bg.muted=true;bg.play().catch(done);});}
/* The agent replies in comic speech bubbles over the clip: video alone for a moment, then bubble 1 by his head, then bubble 2 with the amount and buttons. */
function ypOpenBuyChat(id,feature,lead){const rec=ypBuyFor(id);if(lead==null)lead=2000;ypExclusive('yp-apply-review');['yp-apply-review','yp-sale-detail'].forEach(k=>document.getElementById(k)?.remove());const panel=document.createElement('div');panel.id='yp-apply-review';panel.className='yp-steps yp-chat';panel.dataset.step='reply';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Agent response');panel.setAttribute('aria-live','polite');const st=rec.status;const comic=(cls,fill)=>{const b=document.createElement('div');b.className='yp-comic '+cls;fill(b);panel.appendChild(b);};const say=(b,t,cls)=>{const p=document.createElement('p');if(cls)p.className=cls;p.textContent=t;b.appendChild(p);};const pill=(b,label,fn,bid,main)=>{const x=document.createElement('button');x.type='button';x.className='yp-pill'+(main?' yp-pill-main':'');x.id=bid;x.textContent=label;x.addEventListener('click',fn);b.appendChild(x);};let first,second;if(st==='negotiating'){first=null;second=b=>{say(b,ypMoneyText(rec.ask),'yp-comic-amt');pill(b,'Increase my offer',()=>ypOpenBuyStep(id,'offer',feature),'yp-counter-again');pill(b,'Accept '+ypMoneyText(rec.ask),()=>{ypAcceptCounter(id);ypOpenBuyChat(id,feature,600);},'yp-counter-accept',true);pill(b,'Walk away',()=>{ypWalkAway(id);ypOpenBuy(id);},'yp-counter-walk');};}else if(st==='ended'){first=b=>say(b,rec.line||YP_AGENT_LINES.lowball);second=b=>{say(b,'Step 2 of 5','yp-comic-note');say(b,'Try again after '+YP_NEGOTIATION.cooldownDays+' game day.','yp-comic-note');pill(b,'Close',()=>ypOpenBuy(id),'yp-reply-close');};}else{first=b=>say(b,YP_AGENT_LINES.agreed);second=b=>{say(b,'Step 2 of 5','yp-comic-note');say(b,ypMoneyText(rec.agreed),'yp-comic-amt');say(b,st==='approved'?'You are paying cash, so no loan is needed. Next, you sign the contract.':'Next, the bank checks your loan. Nothing is charged until you sign.','yp-comic-note');pill(b,'Next',()=>ypOpenBuyStep(id,'finance',feature),'yp-reply-next',true);};}panel.addEventListener('click',e=>{if(e.target===panel)panel.remove();});document.body.appendChild(panel);if(st==='negotiating'){ypAgentClip('talk',()=>{if(panel.isConnected)comic('yp-comic-2',second);});return;}setTimeout(()=>{if(panel.isConnected)comic('yp-comic-1',first);},lead);setTimeout(()=>{if(panel.isConnected)comic('yp-comic-2',second);},lead+1200);ypAgentClip(st==='ended'?'counter':'office');}
function ypOfferStatus(status){return { 'application-pending':'Pending','approved':'Approved','active':'Tenancy confirmed','withdrawn':'Withdrawn','declined':'Declined','expired':'Expired','cancelled':'Cancelled' }[status]||status;}
function ypHistoryCardStatus(ev,rental){const kind=ev&&ev.kind||'';const status=rental&&rental.status||'';let label='';if(kind==='cancelled'||status==='cancelled')label='Cancelled';else if(kind==='expired')label='Expired';else if(kind==='declined')label='Declined';else if(kind==='withdrawn')label='Withdrawn';else if(kind==='confirmed')label='Tenancy confirmed';else if(kind==='accepted')label='Approved';else if(kind==='applied'&&(!status||status==='available'||status==='application-pending'))label='Pending';else label=ypOfferStatus(status)||'';label=String(label).trim();if(!label)return '';return label.charAt(0).toUpperCase()+label.slice(1);}
/* Pending = still in progress only: waiting on the agent or seller, bank checking, approved and waiting to sign, under contract. A bank 'no', ended talks or walking away are finished, so they live in History and on the property's own card. */
function ypPendingBuys(){return Object.values(ypReadBuys().buys).filter(b=>['negotiating','finance-choice','finance-pending','approved','contract'].includes(b.status));}
/* old saves: a declined purchase with no History row gets one, so it is still recorded after leaving Pending */
(function ypMigrateDeclinedBuys(){try{const evs=ypReadHistory().events||[];const add=[];Object.values(ypReadBuys().buys).forEach(b=>{if(b.status!=='declined'||evs.some(e=>e.propertyId===b.id&&e.kind==='financeDeclined'))return;const g=Number.isFinite(+b.approveGameMs)?+b.approveGameMs:0;const ev=ypHistoryEvent(b.id,'financeDeclined',g,b.declineWhy||'The bank said no to this loan',Number.isFinite(+b.approveAt)?+b.approveAt:null);if(ev)add.push(ev);});if(add.length)ypRecordHistory(add);}catch(e){}})();
function ypTimerStart(id,kinds,gameKey,wallKey,rec){const evs=(ypReadHistory().events||[]).filter(e=>e&&e.propertyId===id&&kinds.includes(e.kind)).sort((a,b)=>(+b.gameMs||0)-(+a.gameMs||0));const ev=evs[0];const game=rec&&Number.isFinite(+rec[gameKey])?+rec[gameKey]:(ev&&Number.isFinite(+ev.gameMs)?+ev.gameMs:null);const wall=rec&&Number.isFinite(+rec[wallKey])?+rec[wallKey]:(ev&&Number.isFinite(+ev.at)?+ev.at:null);return {game,wall};}
function ypCapDue(due,now,duration,start){if(!Number.isFinite(+due)||!(duration>0))return due;const left=+due-now;if(!(left>duration+1000))return due;if(Number.isFinite(+start)&&start<=now)return now+Math.max(0,duration-(now-start));return now+duration;}
function ypMigrateOversizedTimers(){const clock=ypReadClock();const now=ypGameMs(clock),wall=clock.wall,day=ypDayMs(clock),hour=ypHourMs(clock),settle=YP_SETTLE_DAYS*day;let buyChanged=false;const s=ypReadBuys();Object.values(s.buys||{}).forEach(b=>{if(b.status==='contract'&&Number.isFinite(+b.settleGameMs)){const start=ypTimerStart(b.id,['contract']).game;const next=ypCapDue(b.settleGameMs,now,settle,start);if(next!==b.settleGameMs){b.settleGameMs=next;buyChanged=true;}}if(b.status==='finance-pending'){const start=ypTimerStart(b.id,['financeApplied','agreed']);if(Number.isFinite(+b.approveGameMs)){const next=ypCapDue(b.approveGameMs,now,hour,start.game);if(next!==b.approveGameMs){b.approveGameMs=next;buyChanged=true;}}if(Number.isFinite(+b.approveAt)){const next=ypCapDue(b.approveAt,wall,hour,start.wall);if(next!==b.approveAt){b.approveAt=next;buyChanged=true;}}}if(b.status==='ended'&&Number.isFinite(+b.endedGameMs)&&b.endedGameMs>now){b.endedGameMs=now;if(Number.isFinite(+b.endedAt)&&b.endedAt>wall)b.endedAt=wall;buyChanged=true;}});if(buyChanged)ypWriteBuys(s);const store=ypReadStock();let rentChanged=false;(store.rentals||[]).forEach(r=>{if(r.status!=='application-pending')return;const start=ypTimerStart(r.id,['applied'],'appliedGameMs','appliedAt',r);if(Number.isFinite(+r.approveGameMs)){const next=ypCapDue(r.approveGameMs,now,hour,start.game);if(next!==r.approveGameMs){r.approveGameMs=next;rentChanged=true;}}if(Number.isFinite(+r.approveAt)){const next=ypCapDue(r.approveAt,wall,hour,start.wall);if(next!==r.approveAt){r.approveAt=next;rentChanged=true;}}});if(rentChanged)ypWriteStock(store);}
if(window.__ypClockFrom){ypRescaleClockRecords(window.__ypClockFrom,CFG.weekMs);delete window.__ypClockFrom;}
try{ypMigrateOversizedTimers();}catch(e){}

function ypPendingOfferRows(store){return (store&&store.rentals||[]).filter(r=>r&&(r.status==='application-pending'||r.status==='approved'||(r.status==='active'&&(r.moveStep==='report'||r.moveStep==='keys'))));}
function ypOpenPendingOffers(){
 ypExclusive('yp-pending');
 ypUseHome();
 ypSyncSample(ypReadClock());
 let panel=document.getElementById('yp-pending');
 if(panel)panel.remove();
 panel=document.createElement('div');
 panel.id='yp-pending';
 panel.setAttribute('role','dialog');
 panel.setAttribute('aria-labelledby','yp-pending-title');
 const card=document.createElement('div');
 card.className='card';
 const shut=()=>{panel.remove();ypUseHome();};
 const head=ypCardHeader({title:'Pending Offers',titleId:'yp-pending-title',onClose:shut});
 card.appendChild(head);
 const rows=ypPendingOfferRows(ypReadStock());
 const buys=ypPendingBuys();
 if(!rows.length&&!buys.length){
  const empty=document.createElement('p');
  empty.id='yp-pending-empty';
  empty.textContent='Nothing pending right now. Offers and rental applications you are waiting on will show here. Finished ones are in Property History.';
  card.appendChild(empty);
 }else{
  const note=document.createElement('p');
  note.textContent='What is happening with each property now. Tap a row to pick up where you left off.';
  card.appendChild(note);
 }
 rows.map(ypPendingRentItem).concat(buys.map(ypPendingBuyItem)).sort((x,y)=>y.startMs-x.startMs).forEach(it=>card.appendChild(ypDetailRow({title:it.title,id:it.id,what:it.what,next:it.next,when:it.when,data:{id:it.key},onClick:()=>{panel.remove();it.onResume();}})));
 const hist=document.createElement('button');
 hist.type='button';
 hist.className='btn buy';
 hist.id='yp-open-history';
 hist.textContent='Property History';
 hist.addEventListener('click',()=>{panel.remove();ypOpenPropertyHistory();});
 card.append(hist);
 panel.appendChild(card);
 document.body.appendChild(panel);
}
function ypSavedTenancyLabel(){const lease=typeof G!=='undefined'&&G?G.lease:null;const fromLease=lease?+lease.months:NaN;const fromStatus=typeof G!=='undefined'&&G?+G.statusLease:NaN;const months=(fromLease===3||fromLease===6||fromLease===12)?fromLease:((fromStatus===3||fromStatus===6||fromStatus===12)?fromStatus:0);return months?months+' months':'';}
function ypMoneyFmt(n){return typeof fmt==='function'?fmt(n):ypMoneyText(n);}
function ypSumAmounts(items){return (items||[]).reduce((t,it)=>t+(it&&!it.detail&&!it.heading&&!it.subhead&&it.amount!=null&&Number.isFinite(+it.amount)?+it.amount:0),0);}
function ypRoundParts(items,total){const list=(items||[]).filter(Boolean).map(it=>{if(it.heading||it.subhead||it.detail||it.amount==null||!Number.isFinite(+it.amount))return Object.assign({},it);return Object.assign({},it,{amount:Math.round(+it.amount)});});if(total==null)return list;const target=Math.round(+total);const idxs=[];list.forEach((it,i)=>{if(!it.heading&&!it.subhead&&!it.detail&&it.amount!=null&&Number.isFinite(+it.amount))idxs.push(i);});let sum=idxs.reduce((t,i)=>t+list[i].amount,0);if(sum!==target&&idxs.length){let pick=idxs[0],best=-1;idxs.forEach(i=>{if(Math.abs(list[i].amount)>best){best=Math.abs(list[i].amount);pick=i;}});list[pick].amount+=target-sum;}return list;}
function ypFlowItem(item){if(!item)return item;if(item.group||item.items||item.heading||item.subhead||item.result||item.value!=null)return item;const next=Object.assign({},item);if(item.amount!=null&&item.value==null)next.value=ypMoneyText(item.amount);if(item.neg==null&&item.amount!=null)next.neg=+item.amount<0;return next;}
/* Shared collapsible breakdown: a Total line you can tap to open the detail. Collapsed by default. */
function ypMoneyGroup(opts){opts=opts||{};const raw=(opts.items||[]).filter(it=>it&&(it.heading||it.subhead||(it.value!=null&&it.value!=='')||(it.amount!=null&&Number.isFinite(+it.amount))));const items=raw.map(it=>{if(it.heading||it.subhead||it.value!=null)return it;return Object.assign({},it,{value:ypMoneyText(it.amount)});});const wrap=document.createElement('div');wrap.className='yp-money-group'+(opts.kind?' yp-money-'+opts.kind:'');if(opts.id)wrap.id=opts.id;const btn=document.createElement('button');btn.type='button';btn.className='yp-money-toggle';btn.setAttribute('aria-expanded','false');const lab=document.createElement('span');lab.className='yp-money-lab';const title=document.createElement('span');title.className='yp-money-title';title.textContent=opts.label||opts.group||'';lab.appendChild(title);if(opts.hint){const hint=document.createElement('span');hint.className='yp-hint';hint.textContent=opts.hint;lab.appendChild(hint);}const right=document.createElement('span');right.className='yp-money-right';const val=document.createElement('span');val.className='yp-money-val';let shown=opts.value;if(shown==null){const n=opts.total!=null?opts.total:ypSumAmounts(raw);shown=typeof n==='number'||(n!=null&&Number.isFinite(+n))?ypMoneyFmt(+n):String(n||'');}else if(typeof shown==='number')shown=ypMoneyFmt(shown);val.textContent=shown;if(opts.valId)val.id=opts.valId;const chev=document.createElement('span');chev.className='yp-money-chev';chev.setAttribute('aria-hidden','true');chev.textContent='\u25BE';right.append(val,chev);btn.append(lab,right);const body=document.createElement('div');body.className='yp-money-body';body.hidden=true;const gid='yp-mg-'+(opts.id||Math.random().toString(36).slice(2,8));body.id=gid;btn.setAttribute('aria-controls',gid);body.appendChild(ypFlow(items));const setOpen=open=>{btn.setAttribute('aria-expanded',String(!!open));body.hidden=!open;wrap.classList.toggle('yp-open',!!open);chev.textContent=open?'\u25B4':'\u25BE';btn.setAttribute('aria-label',(opts.label||opts.group||'Breakdown')+' '+val.textContent+', '+(open?'hide':'show')+' breakdown');};setOpen(!!opts.open);btn.addEventListener('click',()=>setOpen(btn.getAttribute('aria-expanded')!=='true'));wrap.append(btn,body);return wrap;}
function ypWeekResult(item){item=item||{};const wrap=document.createElement('div');wrap.className='yp-week-result yp-week-'+(item.kind==='short'?'short':'save');wrap.dataset.label=item.label||'';const lab=document.createElement('div');lab.className='yp-week-lab';const title=document.createElement('div');title.className='yp-week-title';title.textContent=item.label||'';lab.appendChild(title);if(item.hint){const hint=document.createElement('div');hint.className='yp-hint';hint.textContent=item.hint;lab.appendChild(hint);}const val=document.createElement('div');val.className='yp-week-val';val.textContent=item.value||'';wrap.append(lab,val);return wrap;}
function ypQuoteSettleItems(q){const rest=Math.max(0,(+q.dep||0)-(+q.payNow||0));const items=[];if(rest>0)items.push({label:'Rest of deposit',hint:'Paid at settlement',amount:rest});items.push({label:'Stamp duty',hint:'QLD transfer duty',amount:+q.duty||0});items.push({label:'Mortgage insurance',hint:q.lmi?'Deposit under 20%':'None with 20% or more',amount:+q.lmi||0,id:'yp-q-lmi'});items.push({label:'Legal fees',hint:'Conveyancing',amount:+q.legal||0});if(+q.ins)items.push({label:'Property insurance',hint:'First year',amount:+q.ins});return items;}
function ypRecSettleItems(rec){const rest=Math.max(0,(+rec.dep||0)-(+rec.payNow||0)),lmi=+rec.lmi||0,legal=(+rec.atSettle||0)-rest-(+rec.duty||0)-lmi;const items=[];if(rest>0)items.push({label:'Rest of deposit',hint:'The rest of your deposit',amount:rest});items.push({label:'Stamp duty',hint:'QLD transfer duty',amount:+rec.duty||0});if(lmi)items.push({label:'Mortgage insurance',hint:'Deposit under 20%',amount:lmi});if(Math.round(legal))items.push({label:'Legal fees',hint:'Conveyancing',amount:legal});return items;}
function ypFlow(rows){const box=document.createElement('div');box.className='yp-flow-list';let flow=null;const end=()=>{flow=null;};const ensure=()=>{if(!flow){flow=document.createElement('dl');flow.className='yp-flow';box.appendChild(flow);}return flow;};(rows||[]).forEach(item=>{item=ypFlowItem(item);if(item&&item.heading){end();const hd=document.createElement('div');hd.className='yp-flow-head';hd.textContent=item.heading;box.appendChild(hd);return;}if(item&&item.subhead){end();const hd=document.createElement('div');hd.className='yp-flow-subhead';if(item.propertyId){hd.appendChild(ypPropertyLink(item.propertyId));const sub=item.place||(typeof ypPropPlace==='function'?ypPropPlace(item.propertyId):'');if(sub)hd.append(' · '+sub);}else hd.textContent=item.label||'';box.appendChild(hd);return;}if(item&&(item.group||item.items)){end();box.appendChild(ypMoneyGroup(item));return;}if(item&&item.result){end();box.appendChild(ypWeekResult(item));return;}if(!item||item.value==null||item.value==='')return;const row=document.createElement('div');row.dataset.label=item.label||'';if(item.detail)row.classList.add('yp-subtotal');const dt=document.createElement('dt');dt.textContent=item.label||'';if(item.hint){const hint=document.createElement('span');hint.className='yp-hint';hint.textContent=item.hint;dt.appendChild(hint);}if(item.propertyId){const pl=document.createElement('span');pl.className='yp-hint yp-row-id';pl.appendChild(ypPropertyLink(item.propertyId));dt.appendChild(pl);}const dd=document.createElement('dd');if(item.id)dd.id=item.id;if(item.onClick){const a=document.createElement('a');a.href='#';a.className='yp-link';a.textContent=String(item.value);if(item.codeFor)a.dataset.ypCode=item.codeFor;a.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();item.onClick();});dd.appendChild(a);}else{dd.textContent=String(item.value);if(item.codeFor)dd.dataset.ypCode=item.codeFor;}if(item.neg)dd.classList.add('yp-neg');row.append(dt,dd);ensure().appendChild(row);});return box;}

function ypLeaseWeeksLeft(){const L=typeof G!=='undefined'&&G?G.lease:null;if(!L||L.broken||L.m2m||!Number.isFinite(+L.end)||L.end<=G.week)return null;return L.end-G.week;}
function ypLivingFacts(){if(typeof G==='undefined'||!G||typeof housing!=='function')return {status:'',time:null};const h=housing();if(h==='home')return {status:'Property owner',time:null};if(h==='family'){const home=G.famHome;if(home&&home.room)return {status:'Room Sharing',time:null};if(home)return {status:typeof boardWk==='function'&&boardWk()>0?'Boarding':'Living with family or friends',time:null};return {status:'',time:null};}if(G.homeChosen&&G.lease&&!G.lease.broken)return {status:'Renting',time:ypLeaseWeeksLeft()};if(G.homeChosen)return {status:'Renting',time:null};if(G.clockOn)return {status:'Boarding',time:null};if(G.statusPick==='rent')return {status:'Renting',time:null};return {status:'',time:null};}
function ypAwayRows(weeks,cashDelta,ledger){const n=weeks|0;const live=ypLivingFacts();const rows=[{label:'Game weeks passed',value:String(n),id:'yp-away-weeks'}];const income=ledger&&Number.isFinite(+ledger.income)?+ledger.income:null;const expense=ledger&&Number.isFinite(+ledger.expense)?+ledger.expense:0;if(income!=null)rows.push({label:'Income received',value:fmt(income),neg:income<0,id:'yp-away-income'});if(Number.isFinite(+cashDelta)&&(income==null||expense!==0||Math.round(+cashDelta)!==Math.round(income)))rows.push({label:'Extra savings',value:fmt(+cashDelta),neg:+cashDelta<0,id:'yp-away-cash'});if(typeof bank==='function'){const power=bank().power;if(Number.isFinite(+power))rows.push({label:'Borrowing power',value:fmt(power),id:'yp-away-power'});}if(live.status)rows.push({label:'Living status',value:live.status,id:'yp-away-status'});if(live.time!=null)rows.push({label:'Time left',value:live.time+(live.time===1?' week':' weeks'),id:'yp-away-time'});return rows;}
function ypShowAwayCard(weeks,cashDelta,ledger){const n=weeks|0;if(!(n>0)||!Number.isFinite(+cashDelta))return;ypExclusive('yp-away');const old=document.getElementById('yp-away');if(old)old.remove();const panel=document.createElement('div');panel.id='yp-away';panel.setAttribute('role','dialog');panel.setAttribute('aria-labelledby','yp-away-title');const card=document.createElement('div');card.className='card yp-listing';const shut=()=>{panel.remove();ypUseHome();};const head=ypCardHeader({title:'While you were away',titleId:'yp-away-title',id:'yp-away-x',onClose:shut});const close=document.createElement('button');close.type='button';close.className='yp-close';close.id='yp-away-close';close.textContent='Close';close.addEventListener('click',shut);card.append(head,ypFlow(ypAwayRows(n,cashDelta,ledger)),close);panel.appendChild(card);document.body.appendChild(panel);ypUseHome();}
function ypCardHeader(opts){opts=opts||{};const head=document.createElement('header');head.className='yp-card-head';const titles=document.createElement('div');titles.className='yp-card-titles';if(opts.kicker){const eye=document.createElement('p');eye.className='yp-kicker';eye.textContent=opts.kicker;titles.appendChild(eye);}const h=document.createElement('h2');if(opts.titleId)h.id=opts.titleId;if(opts.codeFor)h.appendChild(ypPropertyIdLabel(opts.codeFor,{target:opts.codeTarget,onClick:opts.codeClick}));else h.textContent=opts.title||'';titles.appendChild(h);const btn=document.createElement('button');btn.type='button';btn.className='yp-x';if(opts.id)btn.id=opts.id;btn.setAttribute('aria-label','Close');btn.textContent='\u2715';btn.addEventListener('click',event=>{if(event){event.preventDefault();event.stopPropagation();}if(opts.onClose)opts.onClose(event);});head.append(titles,btn);return head;}
function ypHeaderDismiss(head,onClose,id){if(!head||head.querySelector('.yp-x'))return;const kicker=head.querySelector('.yp-kicker');const titleEl=head.querySelector('h2,h3');const codeEl=head.querySelector('[data-yp-code]');const fresh=ypCardHeader({title:titleEl?titleEl.textContent:(head.textContent||''),kicker:kicker?kicker.textContent:'',codeFor:codeEl&&codeEl.dataset.ypCode||'',onClose,id,titleId:titleEl&&titleEl.id});head.className=fresh.className;head.replaceChildren(...fresh.childNodes);}
let ypSoloLock=0;
function ypDialogNodes(){const ids=['yp-history','yp-history-detail','yp-living','yp-apply-review','yp-rent-detail','yp-sale-detail','yp-rent-list','yp-pending','yp-soon','yp-where','yp-prop','yp-property-menu','yp-section-menu','listings','hwov','yp-away','yp-start-fresh','yp-payout','yp-where-live','yp-clock-start'];const nodes=[];ids.forEach(id=>{const el=document.getElementById(id);if(el)nodes.push(el);});const sheet=document.getElementById('sheet');if(sheet&&sheet.classList.contains('open'))nodes.push(sheet);const drawer=document.getElementById('drawer');if(drawer&&drawer.classList.contains('open'))nodes.push(drawer);return nodes;}
function ypHideDialog(el){if(!el)return;if(el.id==='sheet'){const ui=ypGameUI();if(ui&&ui.close)ui.close();return;}if(el.id==='drawer'){const ui=ypGameUI();if(ui&&ui.menu)ui.menu(false);return;}if(el.id==='listings'&&typeof listClose==='function'){listClose();return;}if(el.id==='yp-property-menu'||el.id==='yp-section-menu')document.documentElement.classList.remove('yp-menu-open');if(el.id==='yp-rent-detail')clearInterval(ypAppTimer);if(el.parentNode)el.remove();}
function ypExclusive(keepId){if(ypSoloLock)return;ypSoloLock=1;try{ypDialogNodes().forEach(el=>{if(el.id!==keepId)ypHideDialog(el);});}finally{ypSoloLock=0;}}
