 if(B.boardBack)income.push({label:'Board stops',hint:'Your rent replaces board',amount:B.boardBack});
 const rentIn=Object.values(B.props||{}).filter(p=>(p.rentIn>0||p.biz>0));
 if(rentIn.length){income.push({heading:'Property income'});rentIn.forEach(p=>{income.push({subhead:true,propertyId:p.id,place:ypPropPlace(p.id)});if(p.rentIn)income.push({label:'Rent received',hint:'After management fees',amount:p.rentIn});if(p.biz)income.push({label:'Shop profit',hint:'Average, it changes week to week',amount:p.biz});});}
 else if(B.tenantRent||B.biz){income.push({heading:'Property income'});if(B.tenantRent)income.push({label:'Rent received',hint:'After management fees',amount:B.tenantRent});if(B.biz)income.push({label:'Shop profit',hint:'Average, it changes week to week',amount:B.biz});}
