function ypFeedIcon(tone){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',{home:'M12 3 2 12h3v8h5v-5h4v5h5v-8h3z',trade:'M3 4h18l1 5c0 1.7-1.3 3-3 3s-3-1.3-3-3c0 1.7-1.3 3-3 3s-3-1.3-3-3c0 1.7-1.3 3-3 3s-3-1.3-3-3l1-5zm2 9.5V20h14v-6.5c-.6.3-1.3.5-2 .5v4H7v-4c-.7 0-1.4-.2-2-.5z',other:'M4 21V5l8-3 8 3v16h-6v-5h-4v5zm4-13v2h2V8zm6 0v2h2V8zm-6 4v2h2v-2zm6 0v2h2v-2z'}[YP_FEED_TYPES[tone]?tone:'other']);svg.appendChild(path);return svg;}
function ypFeedRow(ev){const row=document.createElement('div');row.className='yp-feed-row';row.setAttribute('role','button');row.tabIndex=0;row.dataset.id=ev.id;const pic=document.createElement('span');pic.className='yp-feed-pic';const badge=document.createElement('span');badge.className='yp-feed-badge yp-feed-badge--'+(ev.kind==='sold'?'sold':'sale');badge.textContent=ev.kind==='sold'?'SOLD':'FOR SALE';pic.append(ypFeedIcon(ev.tone),badge);const info=document.createElement('span');info.className='yp-feed-info';const when=document.createElement('span');when.className='yp-feed-tag';when.textContent=ypEventClockLabel({gameMs:ev.gameMs});const price=document.createElement('span');price.className='yp-feed-price';price.textContent=fmt(ev.price);const meta=document.createElement('span');meta.className='yp-feed-meta';meta.textContent=[YP_FEED_TYPES[ev.tone]||'Building',ev.area?Number(ev.area).toLocaleString()+' m²':'',ev.by?'Bought by '+ev.by:''].filter(Boolean).join(' · ');const id=document.createElement('span');id.className='yp-feed-id';id.appendChild(ypPropertyLink(ev.id,{target:{lon:ev.lon,lat:ev.lat}}));info.append(when,price,meta,id);row.append(pic,info);row.addEventListener('click',()=>ypGoToProperty(ev));row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();ypGoToProperty(ev);}});return row;}
function ypRenderFeed(){const now=ypFeedNow().ms;const events=ypFeedRead().events.filter(e=>e.gameMs<=now&&ypFeedVisible(e)).slice(0,60);let feed=document.getElementById('yp-feed');const key=events.map(e=>e.key).join(',')||'empty';if(feed&&feed.dataset.key===key)return;if(!feed){feed=document.createElement('div');feed.id='yp-feed';feed.setAttribute('aria-label','Home feed');document.body.appendChild(feed);}feed.dataset.key=key;const card=document.createElement('section');card.className='yp-feed-card';if(events.length)events.forEach(ev=>card.appendChild(ypFeedRow(ev)));else{const note=document.createElement('p');note.className='yp-feed-meta';note.textContent='No properties listed yet.';card.appendChild(note);}feed.replaceChildren(card);}
function ypSyncFeed(){const show=document.documentElement.classList.contains('yp-home')&&!document.getElementById('flow');if(show)ypRenderFeed();const feed=document.getElementById('yp-feed');if(feed)feed.hidden=!show||!feed.childElementCount;}
(function(){let t=0;const run=()=>{clearTimeout(t);t=setTimeout(()=>{ypSyncNav();ypSyncFeed();},60);};const go=()=>{new MutationObserver(run).observe(document.body,{childList:true,subtree:false,attributes:true,attributeFilter:['class']});new MutationObserver(run).observe(document.documentElement,{attributes:true,attributeFilter:['class']});document.addEventListener('click',run,true);setInterval(run,5000);run();};if(document.body)go();else document.addEventListener('DOMContentLoaded',go);})();


(function(){function hookHome(){return true;}hookHome();
function hookAfford(){if(typeof bank!=='function'||bank.__ypAfford)return typeof bank==='function';const origBank=bank;bank=function(extraRentWk,extraBizWk,cashBase){const b=origBank.apply(this,arguments);try{if(typeof ypLoanPower==='function'){const p=ypLoanPower({rentInWk:+extraRentWk||0});b.power=p.power;b.incomePower=p.incomePower;b.svc=p.svc;b.surplus=p.surplusMo;b.hem=p.livingMo;b.existing=p.existingMo;if(b.cashCap!=null)b.cashCap=0;}}catch(e){}return b;};bank.__ypAfford=1;
 if(typeof loanCheck==='function'&&!loanCheck.__ypAfford){const origLC=loanCheck;loanCheck=function(amt,extraRentWk,extraBizWk,cashBase){if(typeof ypLoanPower==='function'){if(amt<=0)return{ok:true,why:[],b:bank(0,0,cashBase)};const p=ypLoanPower({rentInWk:+extraRentWk||0}),b=bank(extraRentWk,extraBizWk,cashBase),why=[];if(amt>p.power)why.push(p.power<=0?"The bank can't lend you more right now because you would spend more than you earn each week.":'The bank will lend you up to '+(typeof fmt==='function'?fmt(p.power):ypMoneyText(p.power))+', but this loan is '+(typeof fmt==='function'?fmt(amt):ypMoneyText(amt))+'.');return{ok:amt<=p.power,why,b};}return origLC.apply(this,arguments);};loanCheck.__ypAfford=1;}
 return true;}if(!hookAfford()||!hookHome()){let k=0;const t=setInterval(()=>{const a=hookAfford(),h=hookHome();if((a&&h)||++k>40)clearInterval(t);},250);}})();

function ypBankCounts(){const box=document.getElementById('bankbox');if(!box||box.querySelector('#yp-bank-counts')||typeof bank!=='function')return;const b=bank(),B=ypWeekBudget(),P=ypMoneyParts(B,'game'),f=ypMoneyFmt,ar=b.ar,n=BANK.termY*12;const top=box.querySelector('#borrowtop')||box;
 const wrap=document.createElement('div');wrap.id='yp-bank-counts';
 const rows=ypFinSummary(P);
 if(typeof G!=='undefined'&&G)rows.push({label:'Savings',hint:'Your cash now',value:f(G.cash)});
 wrap.appendChild(ypFlow(rows));
 const ba=document.createElement('div');
 if(b.power>0){const rep=b.power/annuity(CFG.rateIP,BANK.termY*12);ba.className='banswer';ba.innerHTML='<div>You could borrow about</div><b id="bb_bp">'+f(b.power)+'</b><div class="bsub">What the bank would lend after its own checks, not your leftover money. Repayments would be about <b id="bb_rep">'+f(rep)+'</b> a month</div>';}
 else{ba.className='banswer banswer-no';ba.innerHTML='<div>The bank can\'t lend you more right now</div><div class="bsub">You spend more than you earn each week. Cut costs or earn more, for example rent out a property, then check again.</div>';}
 top.replaceChildren();top.append(wrap,ba);
 const det=box.querySelector('#borrowdetail');
 if(det&&!det.querySelector('#yp-bank-what')){const counted=[];if(b.rentMo){const overlap=typeof ypIsOverlapRent==='function'&&ypIsOverlapRent();if(overlap||(B.lease&&(B.housing==='rent'||B.housing==='home')))counted.push({label:overlap?'Rent, until a new tenant moves in':'Rent you pay',hint:overlap?'':(f((B.lease&&B.lease.rent)||0)+' a week, as the bank counts it each month'),propertyId:B.lease&&B.lease.id,amount:b.rentMo});else counted.push({label:'Board you pay',hint:'Each month, as the bank counts it',amount:b.rentMo});}Object.values(ypReadBuys().buys).filter(x=>(x.status==='owned'||x.status==='contract')&&ypLoanOwing(x)>0).forEach(x=>{const owing=ypLoanOwing(x);counted.push({label:x.status==='owned'?'Home loan':'Loan at settlement',hint:'Amount owing '+f(owing)+', tested at '+(ar*100).toFixed(2)+'%',propertyId:x.id,amount:owing/annuity(ar,n)});});try{let other=0;for(const[,p]of allProps())other+=+p.loan||0;if(other>0)counted.push({label:'Other game loans',hint:'Balance '+f(other)+', tested at '+(ar*100).toFixed(2)+'%',amount:other/annuity(ar,n)});}catch(e){}if(!counted.length)counted.push({label:'Rent and loans',hint:'You have none yet',amount:0});const inner=document.createElement('div');inner.id='yp-bank-what';inner.appendChild(ypFlow([{heading:'What the bank counts'}].concat(counted)));const sum=det.querySelector('summary');if(sum&&sum.nextSibling)det.insertBefore(inner,sum.nextSibling);else det.appendChild(inner);}}
(function(){function hook(){const ui=ypGameUI&&ypGameUI();if(!ui||!ui.lenders||ui.lenders.__ypFin)return !!(ui&&ui.lenders);const o=ui.lenders;ui.lenders=function(){const r=o.apply(this,arguments);try{ypBankCounts();}catch(e){}return r;};ui.lenders.__ypFin=1;return true;}if(!hook()){let k=0;const t=setInterval(()=>{if(hook()||++k>40)clearInterval(t);},250);}})();
